update public.allah_names set fiche_adulte = $v${"nom_arabe": "الرَّحِيمُ", "translit": "Ar-Rahîm", "traduction": "Le Très Miséricordieux", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah accorde Sa miséricorde à Ses serviteurs. Ce nom exprime Sa miséricorde immense et parfaite."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous pouvons espérer la miséricorde d'Allah, rechercher Son pardon et apprendre à être miséricordieux envers les autres."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "ٱلرَّحْمَٰنِ ٱلرَّحِيمِ", "traduction": "« Le Tout Miséricordieux, le Très Miséricordieux. »", "ref": "Sourate Al-Fâtiha, 1:3.", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ", "traduction": "« Et votre Divinité est une divinité unique. Pas de divinité à part Lui, le Tout Miséricordieux, le Très Miséricordieux. »", "ref": "Sourate Al-Baqara, 2:163.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa miséricorde, Son pardon et Sa bienveillance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Ar-Rahîm, accorde-moi Ta miséricorde et pardonne-moi. »", "note": "Formulation personnelle, non présentée comme une invocation prophétique spécifique."}], "numero_source": 2}$v$::jsonb where display_order = 2 and fiche_adulte = $v${"nom_arabe": "الرَّحِيمُ", "translit": "Ar-Rahîm", "traduction": "Le Très Miséricordieux", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah accorde Sa miséricorde à Ses serviteurs. Ce nom exprime Sa miséricorde immense et parfaite."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous pouvons espérer la miséricorde d'Allah, rechercher Son pardon et apprendre à être miséricordieux envers les autres."}, {"type": "preuve", "titre": "Preuves", "arabe": null, "traduction": null, "ref": "Coran 1:3 et 2:163.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa miséricorde, Son pardon et Sa bienveillance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Ar-Rahîm, accorde-moi Ta miséricorde et pardonne-moi. »", "note": "Formulation personnelle, non présentée comme une invocation prophétique spécifique."}], "numero_source": 2}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمَلِكُ", "translit": "Al-Malik", "traduction": "Le Souverain", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est le véritable Souverain. Tout Lui appartient et Son autorité est absolue."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous reconnaissons qu'Allah est le Maître de toute chose et que nous dépendons de Lui."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous remettons nos affaires entre Ses mains et Lui demandons de nous guider dans nos décisions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Malik, guide-moi vers ce qui est juste et bon. »", "note": "Formulation personnelle."}], "numero_source": 3}$v$::jsonb where display_order = 3 and fiche_adulte = $v${"nom_arabe": "الْمَلِكُ", "translit": "Al-Malik", "traduction": "Le Souverain", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est le véritable Souverain. Tout Lui appartient et Son autorité est absolue."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous reconnaissons qu'Allah est le Maître de toute chose et que nous dépendons de Lui."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous remettons nos affaires entre Ses mains et Lui demandons de nous guider dans nos décisions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Malik, guide-moi vers ce qui est juste et bon. »", "note": "Formulation personnelle."}], "numero_source": 3}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْقُدُّوسُ", "translit": "Al-Quddûs", "traduction": "Le Très Saint", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est parfaitement pur et exempt de tout défaut, de toute imperfection et de toute faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah est parfait ; rien de ce qui caractérise les créatures ne peut Lui être attribué de manière semblable."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions et Lui demandons de purifier nos cœurs et nos intentions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Quddûs, purifie mon cœur et améliore mes intentions. »", "note": "Formulation personnelle. La demande de purification est un sens de supplication, pas une promesse attachée à une formule particulière."}], "numero_source": 4}$v$::jsonb where display_order = 4 and fiche_adulte = $v${"nom_arabe": "الْقُدُّوسُ", "translit": "Al-Quddûs", "traduction": "Le Très Saint", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est parfaitement pur et exempt de tout défaut, de toute imperfection et de toute faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah est parfait ; rien de ce qui caractérise les créatures ne peut Lui être attribué de manière semblable."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions et Lui demandons de purifier nos cœurs et nos intentions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Quddûs, purifie mon cœur et améliore mes intentions. »", "note": "Formulation personnelle. La demande de purification est un sens de supplication, pas une promesse attachée à une formule particulière."}], "numero_source": 4}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "السَّلَامُ", "translit": "As-Salâm", "traduction": "La Paix, Celui qui est exempt de toute imperfection", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est exempt de tout défaut et de toute imperfection. Il est la source de la paix et de la sécurité."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous recherchons auprès d'Allah la paix du cœur et la sécurité, tout en sachant que Sa perfection est incomparable à celle des créatures."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la paix, la protection et la tranquillité."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô As-Salâm, accorde la paix à mon cœur et protège-moi. »", "note": "Formulation personnelle."}], "numero_source": 5}$v$::jsonb where display_order = 5 and fiche_adulte = $v${"nom_arabe": "السَّلَامُ", "translit": "As-Salâm", "traduction": "La Paix, Celui qui est exempt de toute imperfection", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est exempt de tout défaut et de toute imperfection. Il est la source de la paix et de la sécurité."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous recherchons auprès d'Allah la paix du cœur et la sécurité, tout en sachant que Sa perfection est incomparable à celle des créatures."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la paix, la protection et la tranquillité."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô As-Salâm, accorde la paix à mon cœur et protège-moi. »", "note": "Formulation personnelle."}], "numero_source": 5}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُؤْمِنُ", "translit": "Al-Mu'min", "traduction": "Celui qui accorde la sécurité et confirme la vérité", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui qui garantit la sécurité, inspire confiance et confirme la vérité de Ses révélations et de Ses promesses."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Notre confiance véritable doit être placée en Allah. Nous apprenons à rechercher auprès de Lui la sécurité et la protection."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la protection, la sécurité et l'apaisement face à une inquiétude."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mu'min, accorde-moi Ta sécurité et raffermis ma confiance en Toi. »", "note": "Formulation personnelle."}], "numero_source": 6}$v$::jsonb where display_order = 6 and fiche_adulte = $v${"nom_arabe": "الْمُؤْمِنُ", "translit": "Al-Mu'min", "traduction": "Celui qui accorde la sécurité et confirme la vérité", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui qui garantit la sécurité, inspire confiance et confirme la vérité de Ses révélations et de Ses promesses."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Notre confiance véritable doit être placée en Allah. Nous apprenons à rechercher auprès de Lui la sécurité et la protection."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la protection, la sécurité et l'apaisement face à une inquiétude."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mu'min, accorde-moi Ta sécurité et raffermis ma confiance en Toi. »", "note": "Formulation personnelle."}], "numero_source": 6}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُهَيْمِنُ", "translit": "Al-Muhaymin", "traduction": "Le Gardien et le Protecteur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah veille sur toute chose, la préserve et en connaît parfaitement la réalité. Rien ne Lui échappe."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous ne sommes jamais hors de la connaissance d'Allah. Il connaît nos actes, nos paroles et ce que nos cœurs renferment."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa protection et lorsque nous avons besoin de nous rappeler que rien n'échappe à Sa connaissance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Muhaymin, veille sur moi et protège-moi par Ta volonté. »", "note": "Formulation personnelle."}], "numero_source": 7}$v$::jsonb where display_order = 7 and fiche_adulte = $v${"nom_arabe": "الْمُهَيْمِنُ", "translit": "Al-Muhaymin", "traduction": "Le Gardien et le Protecteur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah veille sur toute chose, la préserve et en connaît parfaitement la réalité. Rien ne Lui échappe."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous ne sommes jamais hors de la connaissance d'Allah. Il connaît nos actes, nos paroles et ce que nos cœurs renferment."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa protection et lorsque nous avons besoin de nous rappeler que rien n'échappe à Sa connaissance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Muhaymin, veille sur moi et protège-moi par Ta volonté. »", "note": "Formulation personnelle."}], "numero_source": 7}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْعَزِيزُ", "translit": "Al-'Azîz", "traduction": "Le Tout-Puissant, l'Invincible", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah possède la puissance parfaite. Rien ne peut Le vaincre ni s'opposer à Sa volonté."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous devons nous en remettre à la puissance d'Allah plutôt que de croire que nos difficultés sont insurmontables."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", "traduction": "« … Et c'est Lui le Tout-Puissant, le Sage. »", "ref": "Sourate Al-Hachr, 59:24 (fin du verset).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons force, secours et soutien dans une épreuve."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-'Azîz, accorde-moi la force et aide-moi à traverser cette épreuve. »", "note": "Formulation personnelle."}], "numero_source": 8}$v$::jsonb where display_order = 8 and fiche_adulte = $v${"nom_arabe": "الْعَزِيزُ", "translit": "Al-'Azîz", "traduction": "Le Tout-Puissant, l'Invincible", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah possède la puissance parfaite. Rien ne peut Le vaincre ni s'opposer à Sa volonté."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous devons nous en remettre à la puissance d'Allah plutôt que de croire que nos difficultés sont insurmontables."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23 et 59:24.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons force, secours et soutien dans une épreuve."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-'Azîz, accorde-moi la force et aide-moi à traverser cette épreuve. »", "note": "Formulation personnelle."}], "numero_source": 8}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْجَبَّارُ", "translit": "Al-Jabbâr", "traduction": "Le Tout-Puissant, Celui dont la volonté s'accomplit", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui dont la puissance et l'autorité sont absolues. Ce nom comporte également le sens de Celui qui répare et rétablit ce qui est brisé, selon les explications des savants."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Aucune difficulté ne dépasse la puissance d'Allah. Nous pouvons Lui confier nos blessures et nos épreuves."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Son secours, Sa force et le soulagement de nos peines."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Jabbâr, répare ce qui est blessé dans mon cœur et facilite mes difficultés. »", "note": "Formulation personnelle. Ne pas réduire ce nom à une seule traduction française."}], "numero_source": 9}$v$::jsonb where display_order = 9 and fiche_adulte = $v${"nom_arabe": "الْجَبَّارُ", "translit": "Al-Jabbâr", "traduction": "Le Tout-Puissant, Celui dont la volonté s'accomplit", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui dont la puissance et l'autorité sont absolues. Ce nom comporte également le sens de Celui qui répare et rétablit ce qui est brisé, selon les explications des savants."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Aucune difficulté ne dépasse la puissance d'Allah. Nous pouvons Lui confier nos blessures et nos épreuves."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Son secours, Sa force et le soulagement de nos peines."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Jabbâr, répare ce qui est blessé dans mon cœur et facilite mes difficultés. »", "note": "Formulation personnelle. Ne pas réduire ce nom à une seule traduction française."}], "numero_source": 9}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُتَكَبِّرُ", "translit": "Al-Mutakabbir", "traduction": "Le Suprême, le Détenteur de la grandeur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui à qui appartiennent la grandeur et la majesté absolues. Il est au-dessus de toute imperfection et de toute comparaison avec les créatures."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "La grandeur véritable appartient à Allah seul. L'être humain doit rester humble et ne pas s'enorgueillir."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions, reconnaissons Sa grandeur et demandons à être préservés de l'orgueil."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mutakabbir, éloigne de mon cœur l'orgueil et aide-moi à rester humble. »", "note": "Formulation personnelle."}], "numero_source": 10}$v$::jsonb where display_order = 10 and fiche_adulte = $v${"nom_arabe": "الْمُتَكَبِّرُ", "translit": "Al-Mutakabbir", "traduction": "Le Suprême, le Détenteur de la grandeur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui à qui appartiennent la grandeur et la majesté absolues. Il est au-dessus de toute imperfection et de toute comparaison avec les créatures."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "La grandeur véritable appartient à Allah seul. L'être humain doit rester humble et ne pas s'enorgueillir."}, {"type": "preuve", "titre": "Preuve", "arabe": null, "traduction": null, "ref": "Coran 59:23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions, reconnaissons Sa grandeur et demandons à être préservés de l'orgueil."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mutakabbir, éloigne de mon cœur l'orgueil et aide-moi à rester humble. »", "note": "Formulation personnelle."}], "numero_source": 10}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْبَاسِطُ", "translit": "Al-Bâsit", "traduction": "Celui qui étend et accorde avec largesse", "provenance": "Coran — action explicitement mentionnée ; statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Bâsit est associé au sens d'étendre, d'accorder avec largesse et d'ouvrir les possibilités.\n\nAllah accorde à Ses créatures leur subsistance selon Sa sagesse. Il peut élargir les bienfaits et faciliter les situations."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "L'aisance et la difficulté font partie des situations de la vie. Nous devons remercier Allah lorsque les bienfaits sont nombreux et rester patients lorsque les choses deviennent difficiles.\n\nNous ne devons pas mesurer l'amour d'Allah uniquement à la quantité de biens matériels que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ", "traduction": "« Allah restreint et étend, et c'est vers Lui que vous serez ramenés. »", "ref": "Sourate Al-Baqara, 2:245 (fin du verset).", "degre": "coran", "texte": "Attention : le verset contient le verbe « yabsutu » (Il étend), et non nécessairement le nom propre « Al-Bâsit » sous cette forme.\n\nDans le Mushaf, « يَبْصُۜطُ » s'écrit avec la lettre ص surmontée d'un petit س, et se lit « yabsutu »."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "En raison de la divergence sur son établissement comme nom indépendant, privilégier les noms divins établis sans divergence pour les invocations.\n\nOn peut demander à Allah d'élargir notre subsistance licite, de faciliter nos affaires et de nous accorder Ses bienfaits."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, accorde-moi une subsistance bonne et licite, facilite mes affaires et mets Ta bénédiction dans mes bienfaits. »", "note": "Formulation personnelle, non attribuée au Prophète ﷺ."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "DIVERGENCE SUR LE STATUT DU NOM", "texte": "Preuve de l'action : Coran 2:245.\n\nNe pas présenter le nom Al-Bâsit comme unanimement établi sous sa forme nominale."}], "numero_source": 21}$v$::jsonb where display_order = 21 and fiche_adulte = $v${"nom_arabe": "الْبَاسِطُ", "translit": "Al-Bâsit", "traduction": "Celui qui étend et accorde avec largesse", "provenance": "Coran — action explicitement mentionnée ; statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Bâsit est associé au sens d'étendre, d'accorder avec largesse et d'ouvrir les possibilités.\n\nAllah accorde à Ses créatures leur subsistance selon Sa sagesse. Il peut élargir les bienfaits et faciliter les situations."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "L'aisance et la difficulté font partie des situations de la vie. Nous devons remercier Allah lorsque les bienfaits sont nombreux et rester patients lorsque les choses deviennent difficiles.\n\nNous ne devons pas mesurer l'amour d'Allah uniquement à la quantité de biens matériels que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ", "traduction": "« Allah restreint et étend, et c'est vers Lui que vous serez ramenés. »", "ref": "Sourate Al-Baqara, 2:245", "degre": "coran", "texte": "Attention : le verset contient le verbe « yabsutu » (Il étend), et non nécessairement le nom propre « Al-Bâsit » sous cette forme."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "En raison de la divergence sur son établissement comme nom indépendant, privilégier les noms divins établis sans divergence pour les invocations.\n\nOn peut demander à Allah d'élargir notre subsistance licite, de faciliter nos affaires et de nous accorder Ses bienfaits."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, accorde-moi une subsistance bonne et licite, facilite mes affaires et mets Ta bénédiction dans mes bienfaits. »", "note": "Formulation personnelle, non attribuée au Prophète ﷺ."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "DIVERGENCE SUR LE STATUT DU NOM", "texte": "Preuve de l'action : Coran 2:245.\n\nNe pas présenter le nom Al-Bâsit comme unanimement établi sous sa forme nominale."}], "numero_source": 21}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْخَافِضُ", "translit": "Al-Khâfid", "traduction": "Celui qui abaisse", "provenance": "Non établi comme nom divin indépendant.", "statut": "non_etabli", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Khâfid est traditionnellement traduit par « Celui qui abaisse ».\n\nCette appellation est souvent présentée dans les listes populaires des 99 noms. Cependant, son établissement comme nom divin indépendant demande une preuve textuelle recevable."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah élève qui Il veut et abaisse qui Il veut selon Sa sagesse et Sa justice.\n\nIl ne faut jamais attribuer à Allah la moindre injustice."}, {"type": "preuve", "titre": "Preuve et statut documentaire", "arabe": null, "traduction": null, "ref": null, "degre": null, "texte": "Le nom « Al-Khâfid » apparaît dans la liste détaillée traditionnellement attribuée au hadith des 99 noms, mais cette énumération détaillée n'est pas authentiquement établie comme liste prophétique.\n\nNe pas inventer de verset ou de hadith authentique attestant explicitement ce nom."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "Ne pas proposer de formule spécifique commençant par « Yâ Khâfid » tant que son statut comme nom divin indépendant n'est pas établi.\n\nL'utilisateur peut invoquer Allah par des noms établis, en Lui demandant justice, protection et droiture."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, éloigne-moi de l'orgueil, guide-moi vers la justice et aide-moi à rester humble. »", "note": "Formulation personnelle."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "La présence dans la liste populaire des 99 noms ne suffit pas à prouver l'authenticité de cette appellation."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "NON ÉTABLI", "texte": "Le terme Al-Khâfid, comme nom divin indépendant, n'est pas établi de manière suffisamment explicite et incontestable par une preuve authentique.\n\nLe Coran parle d'abaisser et d'élever, mais cela ne prouve pas directement que « Al-Khâfid » est un nom d'Allah."}], "numero_source": 22}$v$::jsonb where display_order = 22 and fiche_adulte = $v${"nom_arabe": "الْخَافِضُ", "translit": "Al-Khâfid", "traduction": "Celui qui abaisse", "provenance": "Statut comme nom divin non établi de manière incontestable.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Khâfid est traditionnellement traduit par « Celui qui abaisse ».\n\nCette appellation est souvent présentée dans les listes populaires des 99 noms. Cependant, son établissement comme nom divin indépendant demande une preuve textuelle recevable."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah élève qui Il veut et abaisse qui Il veut selon Sa sagesse et Sa justice.\n\nIl ne faut pas attribuer à Allah une injustice ou une injustice arbitraire."}, {"type": "preuve", "titre": "Preuve et statut documentaire", "arabe": null, "traduction": null, "ref": null, "degre": null, "texte": "Le nom « Al-Khâfid » apparaît dans la liste détaillée traditionnellement attribuée au hadith des 99 noms, mais cette énumération détaillée n'est pas authentiquement établie comme liste prophétique.\n\nNe pas inventer de verset ou de hadith authentique attestant explicitement ce nom."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "Ne pas proposer de formule spécifique commençant par « Yâ Khâfid » tant que son statut comme nom divin indépendant n'est pas établi.\n\nL'utilisateur peut invoquer Allah par des noms établis, en Lui demandant justice, protection et droiture."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, éloigne-moi de l'orgueil, guide-moi vers la justice et aide-moi à rester humble. »", "note": "Formulation personnelle."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "La présence dans la liste populaire des 99 noms ne suffit pas à prouver l'authenticité de cette appellation."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "STATUT DISCUTÉ / PREUVE À ÉTABLIR", "texte": null}], "numero_source": 22}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْخَبِيرُ", "translit": "Al-Khabîr", "traduction": "Le Parfaitement Informé, Celui qui connaît parfaitement toute chose.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Khabîr signifie qu'Allah possède une connaissance parfaite, complète et profonde de toute chose.\n\nIl connaît ce qui est apparent comme ce qui est caché, les actes comme les intentions, les paroles prononcées comme les pensées que personne d'autre ne peut connaître.\n\nRien ne Lui échappe, même les réalités les plus discrètes ou les plus imperceptibles.\n\nSa connaissance n'est ni limitée, ni acquise progressivement : Allah connaît toute chose parfaitement.\n\nCe nom nous rappelle que nous pouvons être sincères devant Allah même lorsque personne ne voit nos efforts, nos difficultés ou nos bonnes intentions."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Allah connaît parfaitement notre situation, même lorsque nous ne savons pas expliquer ce que nous traversons.\n- Nos intentions ont une importance réelle auprès de Lui.\n- Nous devons chercher la sincérité dans nos actes, même lorsque personne ne nous observe.\n- Nous pouvons Lui confier ce que nous gardons au fond de nous."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ", "traduction": "« Les regards ne peuvent L'atteindre, cependant qu'Il saisit tous les regards. Et Il est le Subtil, le Parfaitement Informé. »", "ref": "Sourate Al-An'âm, 6:103.", "degre": "coran", "texte": "Ce verset cite deux noms d'Allah : Al-Latîf (اللَّطِيف), le Subtil, et Al-Khabîr (الْخَبِير), le Parfaitement Informé.\n\nAutre référence : Sourate Al-Mulk, 67:14."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous souhaitons Lui confier une situation complexe, une intention que les autres ne comprennent pas ou une difficulté que nous n'arrivons pas à exprimer."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui connais parfaitement toute chose, Tu connais ce que je montre et ce que je cache. Guide-moi vers ce qui est bon et purifie mes intentions. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 31}$v$::jsonb where display_order = 31 and fiche_adulte = $v${"nom_arabe": "الْخَبِيرُ", "translit": "Al-Khabîr", "traduction": "Le Parfaitement Informé, Celui qui connaît parfaitement toute chose.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Khabîr signifie qu'Allah possède une connaissance parfaite, complète et profonde de toute chose.\n\nIl connaît ce qui est apparent comme ce qui est caché, les actes comme les intentions, les paroles prononcées comme les pensées que personne d'autre ne peut connaître.\n\nRien ne Lui échappe, même les réalités les plus discrètes ou les plus imperceptibles.\n\nSa connaissance n'est ni limitée, ni acquise progressivement : Allah connaît toute chose parfaitement.\n\nCe nom nous rappelle que nous pouvons être sincères devant Allah même lorsque personne ne voit nos efforts, nos difficultés ou nos bonnes intentions."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Allah connaît parfaitement notre situation, même lorsque nous ne savons pas expliquer ce que nous traversons.\n- Nos intentions ont une importance réelle auprès de Lui.\n- Nous devons chercher la sincérité dans nos actes, même lorsque personne ne nous observe.\n- Nous pouvons Lui confier ce que nous gardons au fond de nous."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« C'est Lui qui est le Créateur, le Parfaitement Connaisseur des réalités les plus subtiles, le Parfaitement Informé. »", "ref": "Sourate Al-An'âm, 6:103.", "degre": "coran", "texte": "Autre référence : Sourate Al-Mulk, 67:14."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous souhaitons Lui confier une situation complexe, une intention que les autres ne comprennent pas ou une difficulté que nous n'arrivons pas à exprimer."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui connais parfaitement toute chose, Tu connais ce que je montre et ce que je cache. Guide-moi vers ce qui est bon et purifie mes intentions. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 31}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْغَفُورُ", "translit": "Al-Ghafûr", "traduction": "Le Très Pardonneur, Celui qui pardonne abondamment.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Ghafûr désigne Allah comme Celui dont le pardon est immense et qui pardonne abondamment à Ses serviteurs lorsqu'ils reviennent sincèrement vers Lui.\n\nCe nom exprime l'étendue de Son pardon : malgré les fautes répétées de l'être humain, la porte du repentir reste ouverte tant que les conditions du repentir sont réunies et que le délai accordé n'est pas dépassé.\n\nAllah connaît nos faiblesses, mais Il nous appelle à ne pas désespérer de Sa miséricorde.\n\nIl ne faut toutefois pas confondre l'espoir en Son pardon avec le fait de persister volontairement dans le péché sans repentir."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Ne jamais désespérer de la miséricorde d'Allah.\n- Reconnaître ses erreurs et demander pardon.\n- Délaisser le péché et regretter sincèrement ses actes.\n- Espérer le pardon d'Allah tout en faisant les efforts nécessaires pour changer."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Informe Mes serviteurs que c'est Moi le Pardonneur, le Très Miséricordieux. »", "ref": "Sourate Al-Hijr, 15:49.", "degre": "coran", "texte": "Autre référence : Sourate Az-Zumar, 39:53."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons pardon pour nos péchés, après une erreur ou dans le cadre de notre repentir."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Ghafûr, pardonne mes péchés, efface mes erreurs et aide-moi à ne pas retourner vers ce qui Te déplaît. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": null, "phonetique": null, "traduction": "Le Prophète ﷺ a enseigné notamment :\n\n« Ô Allah, Tu es Pardonneur et Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, 3513, invocation rapportée dans le hadith de 'Â'isha au sujet de la nuit du Destin.", "degre": "sahih", "texte": "Avis divergents sur son authenticité : At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf).", "note": "Important : cette invocation prophétique emploie le nom Al-'Afuww, et non Al-Ghafûr. Ne pas mélanger les deux noms dans la citation.", "divergence": "At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf)."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 34}$v$::jsonb where display_order = 34 and fiche_adulte = $v${"nom_arabe": "الْغَفُورُ", "translit": "Al-Ghafûr", "traduction": "Le Très Pardonneur, Celui qui pardonne abondamment.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Ghafûr désigne Allah comme Celui dont le pardon est immense et qui pardonne abondamment à Ses serviteurs lorsqu'ils reviennent sincèrement vers Lui.\n\nCe nom exprime l'étendue de Son pardon : malgré les fautes répétées de l'être humain, la porte du repentir reste ouverte tant que les conditions du repentir sont réunies et que le délai accordé n'est pas dépassé.\n\nAllah connaît nos faiblesses, mais Il nous appelle à ne pas désespérer de Sa miséricorde.\n\nIl ne faut toutefois pas confondre l'espoir en Son pardon avec le fait de persister volontairement dans le péché sans repentir."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Ne jamais désespérer de la miséricorde d'Allah.\n- Reconnaître ses erreurs et demander pardon.\n- Délaisser le péché et regretter sincèrement ses actes.\n- Espérer le pardon d'Allah tout en faisant les efforts nécessaires pour changer."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Informe Mes serviteurs que c'est Moi le Pardonneur, le Très Miséricordieux. »", "ref": "Sourate Al-Hijr, 15:49.", "degre": "coran", "texte": "Autre référence : Sourate Az-Zumar, 39:53."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons pardon pour nos péchés, après une erreur ou dans le cadre de notre repentir."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Ghafûr, pardonne mes péchés, efface mes erreurs et aide-moi à ne pas retourner vers ce qui Te déplaît. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": null, "phonetique": null, "traduction": "Le Prophète ﷺ a enseigné notamment :\n\n« Ô Allah, Tu es Pardonneur et Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, 3513, invocation rapportée dans le hadith de 'Â'isha au sujet de la nuit du Destin. Hadith jugé authentique par At-Tirmidhî.", "degre": "sahih", "texte": null, "note": "Important : cette invocation prophétique emploie le nom Al-'Afuww, et non Al-Ghafûr. Ne pas mélanger les deux noms dans la citation."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 34}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُقِيتُ", "translit": "Al-Muqît", "traduction": "Le Pourvoyeur, Celui qui donne à chaque être ce qui lui est nécessaire.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqît est un nom dont les explications des savants comprennent notamment l'idée de Celui qui pourvoit aux besoins de Ses créatures, qui veille sur elles et qui a pleine capacité sur toute chose.\n\nAllah connaît les besoins de chaque être et rien ne Lui échappe.\n\nIl accorde les moyens de subsistance et les ressources nécessaires à Ses créatures selon Sa sagesse.\n\nCe nom nous rappelle que nos moyens de subsistance ne dépendent pas uniquement de nos efforts : ils sont également entre les mains d'Allah.\n\nCela ne signifie pas qu'il faut abandonner les efforts. Le croyant recherche les moyens licites tout en plaçant sa confiance en Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est à l'origine de notre subsistance.\n- Être reconnaissants pour les bienfaits reçus.\n- Rechercher notre subsistance par des moyens licites.\n- Ne pas laisser la peur du manque nous éloigner de notre confiance en Allah."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقِيتًۭا", "traduction": "« … et Allah veille sur toute chose. »", "ref": "Sourate An-Nisâ', 4:85 (fin du verset).", "degre": "coran", "texte": "Le verset contient le nom Al-Muqît dans l'expression arabe « مُقِيتًا ».\n\nAl-Muqît renvoie notamment à Celui qui veille sur toute chose, qui en assure la subsistance et qui a pouvoir sur elle. Il ne faut donc pas réduire son sens à la seule puissance."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faciliter notre subsistance, de nous accorder ce qui est bénéfique et de nous préserver du besoin."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muqît, accorde-moi une subsistance licite et bénie, pourvois à mes besoins et aide-moi à être reconnaissant envers Toi. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 39}$v$::jsonb where display_order = 39 and fiche_adulte = $v${"nom_arabe": "الْمُقِيتُ", "translit": "Al-Muqît", "traduction": "Le Pourvoyeur, Celui qui donne à chaque être ce qui lui est nécessaire.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqît est un nom dont les explications des savants comprennent notamment l'idée de Celui qui pourvoit aux besoins de Ses créatures, qui veille sur elles et qui a pleine capacité sur toute chose.\n\nAllah connaît les besoins de chaque être et rien ne Lui échappe.\n\nIl accorde les moyens de subsistance et les ressources nécessaires à Ses créatures selon Sa sagesse.\n\nCe nom nous rappelle que nos moyens de subsistance ne dépendent pas uniquement de nos efforts : ils sont également entre les mains d'Allah.\n\nCela ne signifie pas qu'il faut abandonner les efforts. Le croyant recherche les moyens licites tout en plaçant sa confiance en Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est à l'origine de notre subsistance.\n- Être reconnaissants pour les bienfaits reçus.\n- Rechercher notre subsistance par des moyens licites.\n- Ne pas laisser la peur du manque nous éloigner de notre confiance en Allah."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« ... et Allah est Puissant sur toute chose. »", "ref": "Sourate An-Nisâ', 4:85.", "degre": "coran", "texte": "Le verset contient le nom Al-Muqît dans l'expression arabe « مُقِيتًا »."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faciliter notre subsistance, de nous accorder ce qui est bénéfique et de nous préserver du besoin."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muqît, accorde-moi une subsistance licite et bénie, pourvois à mes besoins et aide-moi à être reconnaissant envers Toi. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 39}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْوَلِيُّ", "translit": "Al-Waliyy", "traduction": "Le Protecteur, Celui qui prend en charge et soutient Ses serviteurs.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Waliyy désigne Allah comme Celui qui prend en charge Ses serviteurs croyants, les soutient, les guide et veille sur leurs affaires.\n\nIl est leur Protecteur et leur Allié véritable.\n\nSon soutien est parfait et se manifeste selon Sa sagesse. Cela ne signifie pas que les croyants seront exempts de toute épreuve, mais qu'ils peuvent rechercher auprès d'Allah la guidance, le secours et la protection.\n\nIl faut distinguer Al-Waliyy, avec le sens de Protecteur et Allié, de Al-Wâlî, qui apparaît plus loin dans la liste traditionnelle (fiche 77) et qui renvoie à la notion de Celui qui gouverne et administre."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Rechercher la protection et la guidance d'Allah.\n- Placer notre confiance en Lui.\n- Nous rapprocher d'Allah par la foi et les bonnes œuvres.\n- Ne pas faire dépendre notre sécurité spirituelle uniquement des créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah est le Protecteur de ceux qui ont la foi : Il les fait sortir des ténèbres vers la lumière. »", "ref": "Sourate Al-Baqara, 2:257.", "degre": "coran", "texte": "Autre référence : Sourate Ash-Shûrâ, 42:28."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah Sa protection, Sa guidance, Son soutien et Son aide dans nos affaires."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Waliyy, sois mon Protecteur, guide-moi vers ce qui Te satisfait et ne me laisse pas dépendre de mes seules forces. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 55}$v$::jsonb where display_order = 55 and fiche_adulte = $v${"nom_arabe": "الْوَلِيُّ", "translit": "Al-Waliyy", "traduction": "Le Protecteur, Celui qui prend en charge et soutient Ses serviteurs.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Waliyy désigne Allah comme Celui qui prend en charge Ses serviteurs croyants, les soutient, les guide et veille sur leurs affaires.\n\nIl est leur Protecteur et leur Allié véritable.\n\nSon soutien est parfait et se manifeste selon Sa sagesse. Cela ne signifie pas que les croyants seront exempts de toute épreuve, mais qu'ils peuvent rechercher auprès d'Allah la guidance, le secours et la protection.\n\nIl faut distinguer Al-Waliyy, avec le sens de Protecteur et Allié, de Al-Wâlî, qui apparaît plus loin dans la liste traditionnelle et qui renvoie à la notion de Celui qui gouverne et administre."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Rechercher la protection et la guidance d'Allah.\n- Placer notre confiance en Lui.\n- Nous rapprocher d'Allah par la foi et les bonnes œuvres.\n- Ne pas faire dépendre notre sécurité spirituelle uniquement des créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah est le Protecteur de ceux qui ont la foi : Il les fait sortir des ténèbres vers la lumière. »", "ref": "Sourate Al-Baqara, 2:257.", "degre": "coran", "texte": "Autre référence : Sourate Ash-Shûrâ, 42:28."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah Sa protection, Sa guidance, Son soutien et Son aide dans nos affaires."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Waliyy, sois mon Protecteur, guide-moi vers ce qui Te satisfait et ne me laisse pas dépendre de mes seules forces. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 55}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْحَمِيدُ", "translit": "Al-Hamîd", "traduction": "Le Digne de louange, Celui qui mérite toute louange.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hamîd signifie qu'Allah mérite toute louange en raison de Sa perfection, de Ses attributs et de Ses bienfaits.\n\nIl est digne d'être loué dans toutes les situations, car Sa perfection ne dépend pas de la reconnaissance des créatures.\n\nLes êtres humains Le louent pour Ses bienfaits, mais Il mérite également la louange pour ce qu'Il est.\n\nCe nom nous invite à remercier Allah, à Le glorifier et à reconnaître Ses bienfaits dans notre quotidien."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Louer Allah dans les moments faciles comme dans les moments difficiles.\n- Être reconnaissants pour Ses bienfaits.\n- Reconnaître que toute perfection appartient à Allah.\n- Ne pas attribuer à nous-mêmes le mérite exclusif de ce que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ", "traduction": "« … Allah Se suffit à Lui-même et Il est digne de louange. »", "ref": "Sourate Ibrâhîm, 14:8 (fin du verset).", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "إِنَّهُۥ حَمِيدٌۭ مَّجِيدٌۭ", "traduction": "« … Il est digne de louange et de gloire. »", "ref": "Sourate Hûd, 11:73 (fin du verset).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous louons Allah, Le remercions pour Ses bienfaits ou souhaitons Lui exprimer notre reconnaissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hamîd, à Toi revient toute louange. Aide-moi à reconnaître Tes bienfaits et à Te remercier sincèrement en toute circonstance. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 56}$v$::jsonb where display_order = 56 and fiche_adulte = $v${"nom_arabe": "الْحَمِيدُ", "translit": "Al-Hamîd", "traduction": "Le Digne de louange, Celui qui mérite toute louange.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hamîd signifie qu'Allah mérite toute louange en raison de Sa perfection, de Ses attributs et de Ses bienfaits.\n\nIl est digne d'être loué dans toutes les situations, car Sa perfection ne dépend pas de la reconnaissance des créatures.\n\nLes êtres humains Le louent pour Ses bienfaits, mais Il mérite également la louange pour ce qu'Il est.\n\nCe nom nous invite à remercier Allah, à Le glorifier et à reconnaître Ses bienfaits dans notre quotidien."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Louer Allah dans les moments faciles comme dans les moments difficiles.\n- Être reconnaissants pour Ses bienfaits.\n- Reconnaître que toute perfection appartient à Allah.\n- Ne pas attribuer à nous-mêmes le mérite exclusif de ce que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Si vous êtes ingrats, Allah se passe largement de vous. De Ses serviteurs, Il n'agrée pas la mécréance. Et si vous êtes reconnaissants, Il l'agrée pour vous. »", "ref": "Sourate Az-Zumar, 39:7.", "degre": "coran", "texte": "Autre référence : Sourate Ibrâhîm, 14:8.\n\nLe nom Al-Hamîd apparaît également explicitement dans Sourate Hûd, 11:73."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous louons Allah, Le remercions pour Ses bienfaits ou souhaitons Lui exprimer notre reconnaissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hamîd, à Toi revient toute louange. Aide-moi à reconnaître Tes bienfaits et à Te remercier sincèrement en toute circonstance. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 56}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُحْيِي", "translit": "Al-Muhyî", "traduction": "Celui qui donne la vie et qui ressuscite les morts.", "provenance": "Coran — Allah donne la vie (action clairement attestée) ; forme nominale « Al-Muhyî » à préciser.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muhyî désigne Allah comme Celui qui donne la vie.\n\nIl est Celui qui donne l'existence aux êtres vivants, qui fait sortir la vie de ce qui paraît inerte et qui ressuscitera les morts au Jour dernier.\n\nLa vie appartient à Allah et dépend entièrement de Sa volonté.\n\nCe nom nous rappelle que notre existence est un bienfait immense et que nous devons utiliser notre vie pour accomplir ce qui plaît à notre Créateur."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est Celui qui donne la vie.\n- Être reconnaissants pour le bienfait de l'existence.\n- Se rappeler que la vie terrestre est temporaire.\n- Préparer notre retour vers Allah.\n- Ne jamais désespérer de Sa puissance."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Regarde donc les effets de la miséricorde d'Allah, comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts, et Il est Omnipotent. »", "ref": "Sourate Ar-Rûm, 30:50.", "degre": "coran", "texte": "Autre référence : Sourate Fussilat, 41:39."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de vivifier notre cœur par la foi, de nous guider et de nous accorder une vie consacrée à Son obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muhyî, donne vie à mon cœur par la foi, éloigne-moi de ce qui m'éloigne de Toi et aide-moi à consacrer ma vie à ce qui Te satisfait. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "FORME NOMINALE À PRÉCISER", "texte": "Le sens est directement confirmé par le Coran : Allah donne la vie et fait revivre les morts.\n\nLe statut de la forme « Al-Muhyî » comme nom indépendant dépend de la méthode retenue pour établir les noms divins.\n\nCette précision ne remet jamais en cause le fait qu'Allah donne la vie."}], "numero_source": 60}$v$::jsonb where display_order = 60 and fiche_adulte = $v${"nom_arabe": "الْمُحْيِي", "translit": "Al-Muhyî", "traduction": "Celui qui donne la vie et qui ressuscite les morts.", "provenance": "Coran — acte de donner la vie explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muhyî désigne Allah comme Celui qui donne la vie.\n\nIl est Celui qui donne l'existence aux êtres vivants, qui fait sortir la vie de ce qui paraît inerte et qui ressuscitera les morts au Jour dernier.\n\nLa vie appartient à Allah et dépend entièrement de Sa volonté.\n\nCe nom nous rappelle que notre existence est un bienfait immense et que nous devons utiliser notre vie pour accomplir ce qui plaît à notre Créateur."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est Celui qui donne la vie.\n- Être reconnaissants pour le bienfait de l'existence.\n- Se rappeler que la vie terrestre est temporaire.\n- Préparer notre retour vers Allah.\n- Ne jamais désespérer de Sa puissance."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Regarde donc les effets de la miséricorde d'Allah, comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts, et Il est Omnipotent. »", "ref": "Sourate Ar-Rûm, 30:50.", "degre": "coran", "texte": "Autre référence : Sourate Fussilat, 41:39."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de vivifier notre cœur par la foi, de nous guider et de nous accorder une vie consacrée à Son obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muhyî, donne vie à mon cœur par la foi, éloigne-moi de ce qui m'éloigne de Toi et aide-moi à consacrer ma vie à ce qui Te satisfait. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Le Coran atteste explicitement qu'Allah donne la vie et fait revivre les morts. La forme Al-Muhyî est traditionnellement retenue parmi les noms divins. Conserver la référence coranique à l'acte de donner la vie sans lui attribuer un mérite particulier non établi."}], "numero_source": 60}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْحَيُّ", "translit": "Al-Hayy", "traduction": "Le Vivant, Celui dont la vie est parfaite et éternelle.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hayy signifie qu'Allah est le Vivant, Celui dont la vie est parfaite et éternelle.\n\nSa vie n'a ni commencement ni fin. Elle ne dépend d'aucune créature et n'est accompagnée d'aucune faiblesse, fatigue ou disparition.\n\nLa vie des êtres humains est limitée et dépend de leur Créateur. La vie d'Allah, elle, est parfaite et éternelle, conformément à Sa majesté.\n\nCe nom nous rappelle que nous devons nous tourner vers Celui qui ne meurt jamais et qui ne connaît aucune faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est le Vivant éternel.\n- Placer notre confiance en Celui qui ne disparaît jamais.\n- Comprendre que notre existence dépend entièrement de Lui.\n- Ne pas attribuer à Allah les limites propres aux créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de nous soutenir, de nous guider et de nous accorder une foi vivante et sincère."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hayy, Toi le Vivant qui ne meurs jamais, raffermis mon cœur dans la foi et aide-moi à vivre dans Ton obéissance. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ", "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Le Prophète ﷺ invoquait Allah avec cette formule.\n\n« Ô Vivant, ô Celui qui subsiste par Lui-même et par qui tout subsiste, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524.", "degre": "hasan", "texte": null, "note": "Jugé hasan, notamment par Al-Albânî. At-Tirmidhî qualifie sa transmission de « gharîb » (une seule chaîne connue), ce qui n'est pas un jugement de faiblesse."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 62}$v$::jsonb where display_order = 62 and fiche_adulte = $v${"nom_arabe": "الْحَيُّ", "translit": "Al-Hayy", "traduction": "Le Vivant, Celui dont la vie est parfaite et éternelle.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hayy signifie qu'Allah est le Vivant, Celui dont la vie est parfaite et éternelle.\n\nSa vie n'a ni commencement ni fin. Elle ne dépend d'aucune créature et n'est accompagnée d'aucune faiblesse, fatigue ou disparition.\n\nLa vie des êtres humains est limitée et dépend de leur Créateur. La vie d'Allah, elle, est parfaite et éternelle, conformément à Sa majesté.\n\nCe nom nous rappelle que nous devons nous tourner vers Celui qui ne meurt jamais et qui ne connaît aucune faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est le Vivant éternel.\n- Placer notre confiance en Celui qui ne disparaît jamais.\n- Comprendre que notre existence dépend entièrement de Lui.\n- Ne pas attribuer à Allah les limites propres aux créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de nous soutenir, de nous guider et de nous accorder une foi vivante et sincère."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hayy, Toi le Vivant qui ne meurs jamais, raffermis mon cœur dans la foi et aide-moi à vivre dans Ton obéissance. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": null, "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Le Prophète ﷺ invoquait Allah avec cette formule.\n\nSens : « Ô Vivant, ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524. Rapporté également dans d'autres recueils.", "degre": null, "texte": null, "note": "À vérifier selon l'édition et la numérotation retenues ; ne pas afficher une gradation sans source précise."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 62}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْقَيُّومُ", "translit": "Al-Qayyûm", "traduction": "Celui qui subsiste par Lui-même et qui fait subsister toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qayyûm signifie qu'Allah existe par Lui-même, sans dépendre de personne, tandis que toute la création dépend de Lui.\n\nIl maintient l'existence de toute chose et veille sur Sa création.\n\nIl n'a besoin ni de repos, ni de sommeil, ni d'aide. Rien ne subsiste sans Sa volonté et Sa puissance.\n\nCe nom nous rappelle notre dépendance totale envers Allah et Sa perfection absolue."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que nous dépendons entièrement d'Allah.\n- Ne pas placer notre confiance absolue dans les créatures.\n- Lui demander de nous soutenir dans toutes nos affaires.\n- Garder à l'esprit qu'Allah ne connaît aucune faiblesse."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons Son soutien, Sa protection et Son aide dans les affaires importantes de notre vie."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qayyûm, Toi qui fais subsister toute chose, prends en charge mes affaires, raffermis ma foi et ne me laisse pas livré à mes seules faiblesses. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ", "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Le Prophète ﷺ invoquait Allah avec cette formule.\n\n« Ô Vivant, ô Celui qui subsiste par Lui-même et par qui tout subsiste, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524.", "degre": "hasan", "texte": null, "note": "Jugé hasan, notamment par Al-Albânî. At-Tirmidhî qualifie sa transmission de « gharîb » (une seule chaîne connue), ce qui n'est pas un jugement de faiblesse."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 63}$v$::jsonb where display_order = 63 and fiche_adulte = $v${"nom_arabe": "الْقَيُّومُ", "translit": "Al-Qayyûm", "traduction": "Celui qui subsiste par Lui-même et qui fait subsister toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qayyûm signifie qu'Allah existe par Lui-même, sans dépendre de personne, tandis que toute la création dépend de Lui.\n\nIl maintient l'existence de toute chose et veille sur Sa création.\n\nIl n'a besoin ni de repos, ni de sommeil, ni d'aide. Rien ne subsiste sans Sa volonté et Sa puissance.\n\nCe nom nous rappelle notre dépendance totale envers Allah et Sa perfection absolue."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que nous dépendons entièrement d'Allah.\n- Ne pas placer notre confiance absolue dans les créatures.\n- Lui demander de nous soutenir dans toutes nos affaires.\n- Garder à l'esprit qu'Allah ne connaît aucune faiblesse."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons Son soutien, Sa protection et Son aide dans les affaires importantes de notre vie."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qayyûm, Toi qui fais subsister toute chose, prends en charge mes affaires, raffermis ma foi et ne me laisse pas livré à mes seules faiblesses. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": null, "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Sens : « Ô Vivant, ô Celui qui subsiste par Lui-même, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524.", "degre": null, "texte": null, "note": null}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 63}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْوَاجِدُ", "translit": "Al-Wâjid", "traduction": "Celui à qui rien ne manque, Celui qui ne perd ni ne manque de rien.", "provenance": "Statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Wâjid est traditionnellement expliqué comme Celui qui ne manque de rien et qui possède une richesse, une puissance et une perfection absolues.\n\nAllah n'a besoin d'aucune chose et aucune réalité ne Lui échappe.\n\nIl ne faut pas comprendre ce nom selon le sens humain du fait de chercher ou de trouver quelque chose après l'avoir perdu. Allah ne connaît ni perte, ni manque, ni recherche liée à une ignorance préalable.\n\nCe nom figure dans certaines énumérations traditionnelles des 99 noms, mais son établissement comme nom indépendant fait l'objet de discussions. La liste détaillée populaire attribuée au hadith des 99 noms ne constitue pas, à elle seule, une preuve incontestable de chaque nom."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah n'a besoin de personne.\n- Comprendre que toute créature dépend de Lui.\n- Éviter de nous croire indépendants de notre Créateur.\n- Placer notre confiance en Celui qui possède toute perfection."}, {"type": "preuve", "titre": "Éclairage sur le sens (pas une preuve du nom)", "arabe": "يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ", "traduction": "« Ô hommes ! Vous êtes les indigents ayant besoin d'Allah, et Allah est Celui qui Se suffit à Lui-même, le Digne de louange. »", "ref": "Sourate Fâtir, 35:15.", "degre": "coran", "texte": "Ce verset établit qu'Allah est parfaitement indépendant de Ses créatures et que toutes les créatures ont besoin de Lui. Il éclaire un aspect du sens que certains associent à Al-Wâjid, mais ne prouve pas directement que ce terme est un nom divin établi."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "- Présent dans la liste traditionnelle des 99 noms.\n- Son statut comme nom indépendant est discuté.\n- Ne pas présenter la liste détaillée attribuée à At-Tirmidhî comme une preuve authentique incontestable de ce nom."}, {"type": "texte", "titre": "Quand évoquer Allah par ce nom", "texte": "On peut méditer sur le fait qu'Allah n'a besoin de rien et que toute la création dépend de Lui. Par prudence, ne pas présenter une invocation spécifique avec Al-Wâjid comme formule prophétique établie."}, {"type": "invocation", "titre": "Exemple de rappel personnel", "texte": "« Ô Allah, Toi qui n'as besoin de rien, aide-moi à reconnaître ma dépendance envers Toi et à ne rechercher que Ton agrément. »", "note": "Formulation personnelle, et non invocation prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "STATUT DISCUTÉ", "texte": null}], "numero_source": 64}$v$::jsonb where display_order = 64 and fiche_adulte = $v${"nom_arabe": "الْوَاجِدُ", "translit": "Al-Wâjid", "traduction": "Celui à qui rien ne manque, Celui qui ne perd ni ne manque de rien.", "provenance": "Statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Wâjid est traditionnellement expliqué comme Celui qui ne manque de rien et qui possède une richesse, une puissance et une perfection absolues.\n\nAllah n'a besoin d'aucune chose et aucune réalité ne Lui échappe.\n\nIl ne faut pas comprendre ce nom selon le sens humain du fait de chercher ou de trouver quelque chose après l'avoir perdu. Allah ne connaît ni perte, ni manque, ni recherche liée à une ignorance préalable.\n\nCe nom figure dans certaines énumérations traditionnelles des 99 noms, mais son établissement comme nom indépendant fait l'objet de discussions. La liste détaillée populaire attribuée au hadith des 99 noms ne constitue pas, à elle seule, une preuve incontestable de chaque nom."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah n'a besoin de personne.\n- Comprendre que toute créature dépend de Lui.\n- Éviter de nous croire indépendants de notre Créateur.\n- Placer notre confiance en Celui qui possède toute perfection."}, {"type": "preuve", "titre": "Preuve et prudence", "arabe": null, "traduction": "« Allah, Le Seul à être imploré pour ce que nous désirons. »", "ref": "Référence liée au sens : Sourate Al-Ikhlâs, 112:2.", "degre": "coran", "texte": "Le sens général de la perfection et de l'absence de besoin d'Allah est établi dans le Coran.\n\nAutre référence : Sourate Fâtir, 35:15."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "- Présent dans la liste traditionnelle des 99 noms.\n- Son statut comme nom indépendant est discuté.\n- Ne pas présenter la liste détaillée attribuée à At-Tirmidhî comme une preuve authentique incontestable de ce nom."}, {"type": "texte", "titre": "Quand évoquer Allah par ce nom", "texte": "On peut méditer sur le fait qu'Allah n'a besoin de rien et que toute la création dépend de Lui. Par prudence, ne pas présenter une invocation spécifique avec Al-Wâjid comme formule prophétique établie."}, {"type": "invocation", "titre": "Exemple de rappel personnel", "texte": "« Ô Allah, Toi qui n'as besoin de rien, aide-moi à reconnaître ma dépendance envers Toi et à ne rechercher que Ton agrément. »", "note": "Formulation personnelle, et non invocation prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "STATUT DISCUTÉ", "texte": null}], "numero_source": 64}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْقَادِرُ", "translit": "Al-Qâdir", "traduction": "Le Tout-Puissant, Celui qui a pouvoir sur toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qâdir signifie qu'Allah possède une puissance parfaite et qu'Il est capable de toute chose.\n\nRien ne peut Le limiter ou L'empêcher d'accomplir ce qu'Il veut.\n\nLa puissance des créatures est limitée et dépend de Lui. La puissance d'Allah est absolue.\n\nCe nom nous apprend à ne jamais considérer une difficulté comme impossible pour Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître la puissance absolue d'Allah.\n- Garder espoir dans les situations difficiles.\n- Ne pas désespérer de Sa capacité à changer une situation.\n- Placer notre confiance en Lui tout en prenant les moyens licites."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًۭا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ", "traduction": "« Dis : Il est capable (Al-Qâdir) de faire venir contre vous un châtiment d'en haut ou de dessous vos pieds… »", "ref": "Sourate Al-An'âm, 6:65 (début du verset).", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ", "traduction": "« Celui-là n'est-Il pas capable de faire revivre les morts ? »", "ref": "Sourate Al-Qiyâma, 75:40.", "degre": "coran", "texte": "Le verset emploie « بِقَادِرٍ » : Allah est capable de ressusciter les morts."}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةًۭ", "traduction": "« Dis : Certes, Allah est capable de faire descendre un signe. »", "ref": "Sourate Al-An'âm, 6:37 (extrait).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous faisons face à une difficulté qui nous semble insurmontable ou lorsque nous demandons à Allah de faciliter une affaire."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qâdir, Tu es capable de toute chose. Facilite mes affaires, éloigne de moi ce qui est mauvais et guide-moi vers ce qui est bon. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 68}$v$::jsonb where display_order = 69 and fiche_adulte = $v${"nom_arabe": "الْقَادِرُ", "translit": "Al-Qâdir", "traduction": "Le Tout-Puissant, Celui qui a pouvoir sur toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qâdir signifie qu'Allah possède une puissance parfaite et qu'Il est capable de toute chose.\n\nRien ne peut Le limiter ou L'empêcher d'accomplir ce qu'Il veut.\n\nLa puissance des créatures est limitée et dépend de Lui. La puissance d'Allah est absolue.\n\nCe nom nous apprend à ne jamais considérer une difficulté comme impossible pour Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître la puissance absolue d'Allah.\n- Garder espoir dans les situations difficiles.\n- Ne pas désespérer de Sa capacité à changer une situation.\n- Placer notre confiance en Lui tout en prenant les moyens licites."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Ne sait-Il pas, Lui qui a créé, alors que c'est Lui le Compatissant, le Parfaitement Connaisseur ? »\n\nPour une attestation directe de la forme Al-Qâdir :\n\n« Dis : Il est capable de faire venir contre vous un châtiment d'en haut ou de dessous vos pieds. »", "ref": "Sourate Al-An'âm, 6:65.", "degre": "coran", "texte": "Autre référence : Sourate Al-Qiyâma, 75:40."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous faisons face à une difficulté qui nous semble insurmontable ou lorsque nous demandons à Allah de faciliter une affaire."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qâdir, Tu es capable de toute chose. Facilite mes affaires, éloigne de moi ce qui est mauvais et guide-moi vers ce qui est bon. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 68}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُقَدِّمُ", "translit": "Al-Muqaddim", "traduction": "Celui qui fait avancer et qui place en avant selon Sa sagesse.", "provenance": "Sunna authentique.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqaddim est traditionnellement expliqué comme Celui qui fait avancer, donne la priorité ou place en avant ce qu'Il veut selon Sa sagesse.\n\nAllah décide de l'ordre des événements et de ce qui doit être avancé ou retardé.\n\nCe nom est souvent associé à Al-Mu'akhkhir, Celui qui retarde.\n\nLes deux noms sont cités ensemble dans une invocation prophétique authentique. Cette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que les événements se déroulent selon la sagesse d'Allah.\n- Ne pas désespérer lorsque certaines choses prennent du temps.\n- Demander à Allah de faciliter les bonnes initiatives.\n- Faire preuve de patience et de confiance dans Ses décisions."}, {"type": "preuve", "titre": "Preuve authentique", "arabe": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "traduction": "Le Prophète ﷺ disait dans une invocation :\n\nAnta al-Muqaddimu wa anta al-Mu'akhkhir.\n\n« Tu es Celui qui fait avancer et Tu es Celui qui retarde. »", "ref": "Sahîh Al-Boukhârî 1120 et Sahîh Mouslim 771.", "degre": "sahih", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faire avancer une affaire bénéfique, de faciliter une bonne décision et de nous guider vers ce qui est meilleur."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et retarder selon Ta sagesse, fais avancer pour moi ce qui est bénéfique et éloigne ce qui n'est pas bon pour ma religion et ma vie. »", "note": "Cette formulation est personnelle ; la preuve ci-dessus est la formule rapportée dans le hadith."}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA AUTHENTIQUE", "texte": "Attesté explicitement dans la Sunna authentique, dans l'invocation rapportée par Al-Boukhârî et Mouslim.\n\nCette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}], "numero_source": 70}$v$::jsonb where display_order = 71 and fiche_adulte = $v${"nom_arabe": "الْمُقَدِّمُ", "translit": "Al-Muqaddim", "traduction": "Celui qui fait avancer et qui place en avant selon Sa sagesse.", "provenance": "Forme nominale à présenter avec prudence ; employée dans une invocation prophétique authentique.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqaddim est traditionnellement expliqué comme Celui qui fait avancer, donne la priorité ou place en avant ce qu'Il veut selon Sa sagesse.\n\nAllah décide de l'ordre des événements et de ce qui doit être avancé ou retardé.\n\nCe nom est souvent associé à Al-Mu'akhkhir, Celui qui retarde.\n\nIl faut cependant distinguer l'expression du sens de cet acte divin de l'établissement de la forme Al-Muqaddim comme nom indépendant. Les preuves doivent être examinées selon les critères retenus pour les noms divins, et il ne faut pas présenter une interprétation comme un consensus incontestable."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que les événements se déroulent selon la sagesse d'Allah.\n- Ne pas désespérer lorsque certaines choses prennent du temps.\n- Demander à Allah de faciliter les bonnes initiatives.\n- Faire preuve de patience et de confiance dans Ses décisions."}, {"type": "preuve", "titre": "Preuve et prudence", "arabe": null, "traduction": null, "ref": "Référence liée au sens de l'ordre et de la sagesse divine : Sourate Ibrâhîm, 14:4.", "degre": "coran", "texte": "Le Coran établit qu'Allah fait avancer ou retarde selon Sa volonté et Sa sagesse, mais il faut éviter de présenter une occurrence verbale comme une preuve automatique de la forme nominale Al-Muqaddim.\n\nPour l'association traditionnelle de Al-Muqaddim et Al-Mu'akhkhir, une invocation authentique rapportée dans Sahîh Muslim est particulièrement pertinente."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "- Présent dans la liste traditionnelle des 99 noms.\n- La forme nominale Al-Muqaddim est à présenter avec prudence dans une classification fondée sur les preuves explicites.\n- Une invocation prophétique authentique emploie les expressions « Al-Muqaddim » et « Al-Mu'akhkhir »."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faire avancer une affaire bénéfique, de faciliter une bonne décision et de nous guider vers ce qui est meilleur."}, {"type": "prophetique", "titre": "Invocation prophétique authentique à distinguer", "arabe": null, "phonetique": "Anta al-Muqaddimu wa Anta al-Mu'akhkhir.", "traduction": "Le Prophète ﷺ disait notamment :\n\nSens : « C'est Toi qui fais avancer et c'est Toi qui fais retarder. »", "ref": "Sahîh Muslim, 771.", "degre": "sahih", "texte": null, "note": null}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et retarder selon Ta sagesse, fais avancer pour moi ce qui est bénéfique et éloigne ce qui n'est pas bon pour ma religion et ma vie. »", "note": "Cette dernière formulation est personnelle ; la citation précédente est la formule rapportée dans le hadith."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "STATUT DISCUTÉ", "texte": null}], "numero_source": 70}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُؤَخِّرُ", "translit": "Al-Mu'akhkhir", "traduction": "Celui qui retarde, Celui qui fait passer après.", "provenance": "Sunna authentique.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui décide de l'ordre des événements et de leur moment. Il peut retarder une chose, une échéance ou une situation selon Sa sagesse parfaite. Ce qui nous semble tarder n'échappe jamais à Sa connaissance ni à Son décret.\n\nCe Nom est à comprendre en complément d'Al-Muqaddim : Allah est Celui qui fait avancer et Celui qui fait reculer ou retarder. Rien ne se produit indépendamment de Sa volonté."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Faire preuve de patience lorsque les choses prennent du temps.\n- Ne pas désespérer lorsqu'une demande semble tarder à être exaucée.\n- Comprendre que notre perception du moment opportun n'est pas toujours celle qui correspond à la sagesse divine.\n- Placer notre confiance en Allah sans cesser d'accomplir les causes permises."}, {"type": "preuve", "titre": "Preuve authentique", "arabe": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "traduction": "Le Prophète ﷺ disait dans une invocation :\n\nAnta al-Muqaddimu wa anta al-Mu'akhkhir.\n\n« Tu es Celui qui fait avancer et Tu es Celui qui retarde. »", "ref": "Sahîh Al-Boukhârî 1120 et Sahîh Mouslim 771.", "degre": "sahih", "texte": "Authenticité : hadith authentique, rapporté par Al-Boukhârî et Mouslim."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "On peut évoquer ce Nom lorsqu'on demande à Allah de gérer nos affaires avec sagesse, de nous accorder le bon moment pour une chose ou de nous préserver d'une précipitation nuisible."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et qui retardes selon Ta sagesse, accorde-moi ce qui est bon au moment qui est le meilleur pour moi. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA AUTHENTIQUE", "texte": "Attesté explicitement dans la Sunna authentique, dans l'invocation rapportée par Al-Boukhârî et Mouslim.\n\nCette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}], "numero_source": 71}$v$::jsonb where display_order = 72 and fiche_adulte = $v${"nom_arabe": "الْمُؤَخِّرُ", "translit": "Al-Mu'akhkhir", "traduction": "Celui qui retarde, Celui qui fait passer après.", "provenance": "Sunna authentique.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui décide de l'ordre des événements et de leur moment. Il peut retarder une chose, une échéance ou une situation selon Sa sagesse parfaite. Ce qui nous semble tarder n'échappe jamais à Sa connaissance ni à Son décret.\n\nCe Nom est à comprendre en complément d'Al-Muqaddim : Allah est Celui qui fait avancer et Celui qui fait reculer ou retarder. Rien ne se produit indépendamment de Sa volonté."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Faire preuve de patience lorsque les choses prennent du temps.\n- Ne pas désespérer lorsqu'une demande semble tarder à être exaucée.\n- Comprendre que notre perception du moment opportun n'est pas toujours celle qui correspond à la sagesse divine.\n- Placer notre confiance en Allah sans cesser d'accomplir les causes permises."}, {"type": "preuve", "titre": "Preuve authentique", "arabe": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "traduction": "Le Prophète ﷺ disait dans une invocation :\n\nAnta al-Muqaddimu wa anta al-Mu'akhkhir.\n\n« Tu es Celui qui fait avancer et Tu es Celui qui retarde. »", "ref": "Sahih Muslim, hadith 771a.", "degre": "sahih", "texte": "Authenticité : Hadith authentique, rapporté par Muslim."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "On peut évoquer ce Nom lorsqu'on demande à Allah de gérer nos affaires avec sagesse, de nous accorder le bon moment pour une chose ou de nous préserver d'une précipitation nuisible."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et qui retardes selon Ta sagesse, accorde-moi ce qui est bon au moment qui est le meilleur pour moi. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA AUTHENTIQUE", "texte": "Attesté explicitement dans la Sunna authentique, dans l'invocation rapportée par Muslim."}], "numero_source": 71}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْعَفُوُّ", "translit": "Al-'Afuww", "traduction": "Celui qui efface les péchés et pardonne abondamment.", "provenance": "Coran et Sunna.", "statut": "etabli", "classement": "coran_sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-'Afuww. Il pardonne les fautes de Ses serviteurs et peut en effacer les traces. Son pardon est immense et Sa miséricorde dépasse ce que les êtres humains peuvent imaginer.\n\nCe Nom nous rappelle que le croyant ne doit jamais désespérer du pardon d'Allah. Il doit toutefois se repentir sincèrement et s'efforcer de délaisser le péché."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Ne jamais perdre espoir dans le pardon d'Allah.\n- Reconnaître ses erreurs et revenir sincèrement vers Lui.\n- Apprendre à pardonner aux autres lorsque cela est possible et juste.\n- Ne pas banaliser les péchés sous prétexte qu'Allah pardonne."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا", "traduction": "« Allah est certes Celui qui efface les fautes et qui pardonne. »", "ref": "Coran, sourate An-Nisâ' (4), verset 99.", "degre": "coran", "texte": "Autres références : Coran 4:149 et 22:60."}, {"type": "prophetique", "titre": "Invocation prophétique authentique", "arabe": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "phonetique": "Allâhumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'annî.", "traduction": "« Ô Allah, Tu es Celui qui efface les fautes, Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, 3513.", "degre": "sahih", "texte": "'Â'isha رضي الله عنها demanda au Prophète ﷺ quelle invocation prononcer durant la Nuit du Destin. Il lui enseigna cette invocation.", "note": "Avis divergents sur son authenticité : At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf).", "divergence": "At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf)."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande pardon à Allah, particulièrement pendant les moments propices au repentir, comme les dernières nuits du Ramadan."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, Tu es Al-'Afuww, pardonne-moi, efface mes fautes et accepte mon repentir. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN ET SUNNA", "texte": "Attesté explicitement dans le Coran. L'invocation rapportée par At-Tirmidhî fait l'objet d'avis divergents sur son authenticité."}], "numero_source": 81}$v$::jsonb where display_order = 82 and fiche_adulte = $v${"nom_arabe": "الْعَفُوُّ", "translit": "Al-'Afuww", "traduction": "Celui qui efface les péchés et pardonne abondamment.", "provenance": "Coran et Sunna.", "statut": "etabli", "classement": "coran_sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-'Afuww. Il pardonne les fautes de Ses serviteurs et peut en effacer les traces. Son pardon est immense et Sa miséricorde dépasse ce que les êtres humains peuvent imaginer.\n\nCe Nom nous rappelle que le croyant ne doit jamais désespérer du pardon d'Allah. Il doit toutefois se repentir sincèrement et s'efforcer de délaisser le péché."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Ne jamais perdre espoir dans le pardon d'Allah.\n- Reconnaître ses erreurs et revenir sincèrement vers Lui.\n- Apprendre à pardonner aux autres lorsque cela est possible et juste.\n- Ne pas banaliser les péchés sous prétexte qu'Allah pardonne."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا", "traduction": "« Allah est certes Celui qui efface les fautes et qui pardonne. »", "ref": "Coran, sourate An-Nisâ' (4), verset 99.", "degre": "coran", "texte": "Autres références : Coran 4:149 et 22:60."}, {"type": "prophetique", "titre": "Invocation prophétique authentique", "arabe": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "phonetique": "Allâhumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'annî.", "traduction": "« Ô Allah, Tu es Celui qui efface les fautes, Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, hadith 3513.", "degre": "sahih", "texte": "'Â'isha رضي الله عنها demanda au Prophète ﷺ quelle invocation prononcer durant la Nuit du Destin. Il lui enseigna cette invocation.", "note": "Authenticité : Rapporté par At-Tirmidhî, qui le qualifie de « hasan sahih »."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande pardon à Allah, particulièrement pendant les moments propices au repentir, comme les dernières nuits du Ramadan."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, Tu es Al-'Afuww, pardonne-moi, efface mes fautes et accepte mon repentir. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN ET SUNNA", "texte": "Attesté explicitement dans le Coran et dans une invocation prophétique rapportée par At-Tirmidhî."}], "numero_source": 81}$v$::jsonb;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "ذُو الْجَلَالِ وَالْإِكْرَامِ", "translit": "Dhul-Jalâli wal-Ikrâm", "traduction": "Le Détenteur de la majesté et de la générosité.", "provenance": "Coran — expression explicitement attestée.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui possède toute majesté, toute grandeur et toute perfection. Il est également Celui dont la générosité et les bienfaits sont immenses.\n\nCette appellation réunit deux réalités : la majesté d'Allah, qui inspire le respect et la vénération, et Sa générosité, qui suscite l'amour, l'espérance et la gratitude."}, {"type": "texte", "titre": "Ce que cette appellation nous enseigne", "texte": "- Vénérer Allah et reconnaître Sa grandeur.\n- L'aimer, espérer Sa générosité et Lui être reconnaissant.\n- Ne pas oublier que tous les bienfaits viennent de Lui.\n- Réunir dans notre adoration le respect d'Allah et l'espoir en Sa miséricorde."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ", "traduction": "« Seule subsistera la Face de ton Seigneur, Détenteur de la majesté et de la générosité. »", "ref": "Coran, sourate Ar-Rahmân (55), verset 27.", "degre": "coran", "texte": "Le mot « al-Ikrâm » est riche : il évoque la générosité, mais aussi l'honneur, la noblesse et la munificence. Certaines traductions disent « noblesse ».\n\nAutre référence : Coran, sourate Ar-Rahmân (55), verset 78."}, {"type": "texte", "titre": "Quand invoquer Allah par cette appellation", "texte": "Lorsqu'on souhaite glorifier Allah, Lui demander Ses bienfaits et exprimer sa gratitude envers Lui."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui détiens la majesté et la générosité, accorde-moi Ta miséricorde et rapproche-moi de ce qui Te satisfait. »", "note": null}, {"type": "authenticite", "titre": "Authenticité de l'appellation", "badge": "CORAN", "texte": "Expression explicitement attestée dans le Coran."}], "numero_source": 84}$v$::jsonb where display_order = 85 and fiche_adulte = $v${"nom_arabe": "ذُو الْجَلَالِ وَالْإِكْرَامِ", "translit": "Dhul-Jalâli wal-Ikrâm", "traduction": "Le Détenteur de la majesté et de la générosité.", "provenance": "Coran — expression explicitement attestée.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui possède toute majesté, toute grandeur et toute perfection. Il est également Celui dont la générosité et les bienfaits sont immenses.\n\nCette appellation réunit deux réalités : la majesté d'Allah, qui inspire le respect et la vénération, et Sa générosité, qui suscite l'amour, l'espérance et la gratitude."}, {"type": "texte", "titre": "Ce que cette appellation nous enseigne", "texte": "- Vénérer Allah et reconnaître Sa grandeur.\n- L'aimer, espérer Sa générosité et Lui être reconnaissant.\n- Ne pas oublier que tous les bienfaits viennent de Lui.\n- Réunir dans notre adoration le respect d'Allah et l'espoir en Sa miséricorde."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ", "traduction": "« Seule subsistera la Face de ton Seigneur, plein de majesté et de noblesse. »", "ref": "Coran, sourate Ar-Rahmân (55), verset 27.", "degre": "coran", "texte": "Autre référence : Coran, sourate Ar-Rahmân (55), verset 78."}, {"type": "texte", "titre": "Quand invoquer Allah par cette appellation", "texte": "Lorsqu'on souhaite glorifier Allah, Lui demander Ses bienfaits et exprimer sa gratitude envers Lui."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui détiens la majesté et la générosité, accorde-moi Ta miséricorde et rapproche-moi de ce qui Te satisfait. »", "note": null}, {"type": "authenticite", "titre": "Authenticité de l'appellation", "badge": "CORAN", "texte": "Expression explicitement attestée dans le Coran."}], "numero_source": 84}$v$::jsonb;

update public.allah_names set fiche_enfant = fiche_enfant || $v${"statut": "non_etabli"}$v$::jsonb where display_order = 22 and fiche_enfant is not null;
update public.allah_names set fiche_enfant = fiche_enfant || $v${"statut": "divergence", "prudence": "Les savants ne sont pas tous d'accord pour dire que c'est un nom d'Allah.", "dire": "Ô Allah, donne vie à mon cœur."}$v$::jsonb where display_order = 60 and fiche_enfant is not null;
update public.allah_names set fiche_enfant = fiche_enfant || $v${"statut": "etabli", "prudence": null}$v$::jsonb where display_order = 71 and fiche_enfant is not null;

-- Contrôle : fiches qui n'ont PAS reçu la correction (retouchées au ✏️ entre-temps) → à corriger à la main
select display_order, transliteration from public.allah_names where display_order in (2, 3, 4, 5, 6, 7, 8, 9, 10, 21, 22, 31, 34, 39, 55, 56, 60, 62, 63, 64, 69, 71, 72, 82, 85) and fiche_adulte not in ($v${"nom_arabe": "الرَّحِيمُ", "translit": "Ar-Rahîm", "traduction": "Le Très Miséricordieux", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah accorde Sa miséricorde à Ses serviteurs. Ce nom exprime Sa miséricorde immense et parfaite."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous pouvons espérer la miséricorde d'Allah, rechercher Son pardon et apprendre à être miséricordieux envers les autres."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "ٱلرَّحْمَٰنِ ٱلرَّحِيمِ", "traduction": "« Le Tout Miséricordieux, le Très Miséricordieux. »", "ref": "Sourate Al-Fâtiha, 1:3.", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ", "traduction": "« Et votre Divinité est une divinité unique. Pas de divinité à part Lui, le Tout Miséricordieux, le Très Miséricordieux. »", "ref": "Sourate Al-Baqara, 2:163.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa miséricorde, Son pardon et Sa bienveillance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Ar-Rahîm, accorde-moi Ta miséricorde et pardonne-moi. »", "note": "Formulation personnelle, non présentée comme une invocation prophétique spécifique."}], "numero_source": 2}$v$::jsonb, $v${"nom_arabe": "الْمَلِكُ", "translit": "Al-Malik", "traduction": "Le Souverain", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est le véritable Souverain. Tout Lui appartient et Son autorité est absolue."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous reconnaissons qu'Allah est le Maître de toute chose et que nous dépendons de Lui."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous remettons nos affaires entre Ses mains et Lui demandons de nous guider dans nos décisions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Malik, guide-moi vers ce qui est juste et bon. »", "note": "Formulation personnelle."}], "numero_source": 3}$v$::jsonb, $v${"nom_arabe": "الْقُدُّوسُ", "translit": "Al-Quddûs", "traduction": "Le Très Saint", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est parfaitement pur et exempt de tout défaut, de toute imperfection et de toute faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah est parfait ; rien de ce qui caractérise les créatures ne peut Lui être attribué de manière semblable."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions et Lui demandons de purifier nos cœurs et nos intentions."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Quddûs, purifie mon cœur et améliore mes intentions. »", "note": "Formulation personnelle. La demande de purification est un sens de supplication, pas une promesse attachée à une formule particulière."}], "numero_source": 4}$v$::jsonb, $v${"nom_arabe": "السَّلَامُ", "translit": "As-Salâm", "traduction": "La Paix, Celui qui est exempt de toute imperfection", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est exempt de tout défaut et de toute imperfection. Il est la source de la paix et de la sécurité."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous recherchons auprès d'Allah la paix du cœur et la sécurité, tout en sachant que Sa perfection est incomparable à celle des créatures."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la paix, la protection et la tranquillité."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô As-Salâm, accorde la paix à mon cœur et protège-moi. »", "note": "Formulation personnelle."}], "numero_source": 5}$v$::jsonb, $v${"nom_arabe": "الْمُؤْمِنُ", "translit": "Al-Mu'min", "traduction": "Celui qui accorde la sécurité et confirme la vérité", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui qui garantit la sécurité, inspire confiance et confirme la vérité de Ses révélations et de Ses promesses."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Notre confiance véritable doit être placée en Allah. Nous apprenons à rechercher auprès de Lui la sécurité et la protection."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons la protection, la sécurité et l'apaisement face à une inquiétude."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mu'min, accorde-moi Ta sécurité et raffermis ma confiance en Toi. »", "note": "Formulation personnelle."}], "numero_source": 6}$v$::jsonb, $v${"nom_arabe": "الْمُهَيْمِنُ", "translit": "Al-Muhaymin", "traduction": "Le Gardien et le Protecteur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah veille sur toute chose, la préserve et en connaît parfaitement la réalité. Rien ne Lui échappe."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous ne sommes jamais hors de la connaissance d'Allah. Il connaît nos actes, nos paroles et ce que nos cœurs renferment."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Sa protection et lorsque nous avons besoin de nous rappeler que rien n'échappe à Sa connaissance."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Muhaymin, veille sur moi et protège-moi par Ta volonté. »", "note": "Formulation personnelle."}], "numero_source": 7}$v$::jsonb, $v${"nom_arabe": "الْعَزِيزُ", "translit": "Al-'Azîz", "traduction": "Le Tout-Puissant, l'Invincible", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah possède la puissance parfaite. Rien ne peut Le vaincre ni s'opposer à Sa volonté."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Nous devons nous en remettre à la puissance d'Allah plutôt que de croire que nos difficultés sont insurmontables."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", "traduction": "« … Et c'est Lui le Tout-Puissant, le Sage. »", "ref": "Sourate Al-Hachr, 59:24 (fin du verset).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons force, secours et soutien dans une épreuve."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-'Azîz, accorde-moi la force et aide-moi à traverser cette épreuve. »", "note": "Formulation personnelle."}], "numero_source": 8}$v$::jsonb, $v${"nom_arabe": "الْجَبَّارُ", "translit": "Al-Jabbâr", "traduction": "Le Tout-Puissant, Celui dont la volonté s'accomplit", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui dont la puissance et l'autorité sont absolues. Ce nom comporte également le sens de Celui qui répare et rétablit ce qui est brisé, selon les explications des savants."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Aucune difficulté ne dépasse la puissance d'Allah. Nous pouvons Lui confier nos blessures et nos épreuves."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous demandons Son secours, Sa force et le soulagement de nos peines."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Jabbâr, répare ce qui est blessé dans mon cœur et facilite mes difficultés. »", "note": "Formulation personnelle. Ne pas réduire ce nom à une seule traduction française."}], "numero_source": 9}$v$::jsonb, $v${"nom_arabe": "الْمُتَكَبِّرُ", "translit": "Al-Mutakabbir", "traduction": "Le Suprême, le Détenteur de la grandeur", "provenance": "Coran", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Signification", "texte": "Allah est Celui à qui appartiennent la grandeur et la majesté absolues. Il est au-dessus de toute imperfection et de toute comparaison avec les créatures."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "La grandeur véritable appartient à Allah seul. L'être humain doit rester humble et ne pas s'enorgueillir."}, {"type": "preuve", "titre": "Preuve", "arabe": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "traduction": "« C'est Lui, Allah, en dehors de qui il n'y a pas de divinité : le Souverain, le Très Saint, la Paix, Celui qui accorde la sécurité, le Gardien, le Tout-Puissant, Celui dont la volonté s'accomplit, le Suprême. Gloire à Allah ! Il est au-dessus de ce qu'ils Lui associent. »", "ref": "Sourate Al-Hachr, 59:23.", "degre": "coran", "texte": "Traduction du sens, avec les mêmes mots que les titres des fiches 3 à 10."}, {"type": "texte", "titre": "Quand L'invoquer", "texte": "Lorsque nous Le glorifions, reconnaissons Sa grandeur et demandons à être préservés de l'orgueil."}, {"type": "invocation", "titre": "Invocation proposée", "texte": "« Ô Al-Mutakabbir, éloigne de mon cœur l'orgueil et aide-moi à rester humble. »", "note": "Formulation personnelle."}], "numero_source": 10}$v$::jsonb, $v${"nom_arabe": "الْبَاسِطُ", "translit": "Al-Bâsit", "traduction": "Celui qui étend et accorde avec largesse", "provenance": "Coran — action explicitement mentionnée ; statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Bâsit est associé au sens d'étendre, d'accorder avec largesse et d'ouvrir les possibilités.\n\nAllah accorde à Ses créatures leur subsistance selon Sa sagesse. Il peut élargir les bienfaits et faciliter les situations."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "L'aisance et la difficulté font partie des situations de la vie. Nous devons remercier Allah lorsque les bienfaits sont nombreux et rester patients lorsque les choses deviennent difficiles.\n\nNous ne devons pas mesurer l'amour d'Allah uniquement à la quantité de biens matériels que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ", "traduction": "« Allah restreint et étend, et c'est vers Lui que vous serez ramenés. »", "ref": "Sourate Al-Baqara, 2:245 (fin du verset).", "degre": "coran", "texte": "Attention : le verset contient le verbe « yabsutu » (Il étend), et non nécessairement le nom propre « Al-Bâsit » sous cette forme.\n\nDans le Mushaf, « يَبْصُۜطُ » s'écrit avec la lettre ص surmontée d'un petit س, et se lit « yabsutu »."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "En raison de la divergence sur son établissement comme nom indépendant, privilégier les noms divins établis sans divergence pour les invocations.\n\nOn peut demander à Allah d'élargir notre subsistance licite, de faciliter nos affaires et de nous accorder Ses bienfaits."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, accorde-moi une subsistance bonne et licite, facilite mes affaires et mets Ta bénédiction dans mes bienfaits. »", "note": "Formulation personnelle, non attribuée au Prophète ﷺ."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "DIVERGENCE SUR LE STATUT DU NOM", "texte": "Preuve de l'action : Coran 2:245.\n\nNe pas présenter le nom Al-Bâsit comme unanimement établi sous sa forme nominale."}], "numero_source": 21}$v$::jsonb, $v${"nom_arabe": "الْخَافِضُ", "translit": "Al-Khâfid", "traduction": "Celui qui abaisse", "provenance": "Non établi comme nom divin indépendant.", "statut": "non_etabli", "classement": "discute", "sections": [{"type": "texte", "titre": "Signification", "texte": "Al-Khâfid est traditionnellement traduit par « Celui qui abaisse ».\n\nCette appellation est souvent présentée dans les listes populaires des 99 noms. Cependant, son établissement comme nom divin indépendant demande une preuve textuelle recevable."}, {"type": "texte", "titre": "Ce que ce nom nous apprend", "texte": "Allah élève qui Il veut et abaisse qui Il veut selon Sa sagesse et Sa justice.\n\nIl ne faut jamais attribuer à Allah la moindre injustice."}, {"type": "preuve", "titre": "Preuve et statut documentaire", "arabe": null, "traduction": null, "ref": null, "degre": null, "texte": "Le nom « Al-Khâfid » apparaît dans la liste détaillée traditionnellement attribuée au hadith des 99 noms, mais cette énumération détaillée n'est pas authentiquement établie comme liste prophétique.\n\nNe pas inventer de verset ou de hadith authentique attestant explicitement ce nom."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom ?", "texte": "Ne pas proposer de formule spécifique commençant par « Yâ Khâfid » tant que son statut comme nom divin indépendant n'est pas établi.\n\nL'utilisateur peut invoquer Allah par des noms établis, en Lui demandant justice, protection et droiture."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, éloigne-moi de l'orgueil, guide-moi vers la justice et aide-moi à rester humble. »", "note": "Formulation personnelle."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "La présence dans la liste populaire des 99 noms ne suffit pas à prouver l'authenticité de cette appellation."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "NON ÉTABLI", "texte": "Le terme Al-Khâfid, comme nom divin indépendant, n'est pas établi de manière suffisamment explicite et incontestable par une preuve authentique.\n\nLe Coran parle d'abaisser et d'élever, mais cela ne prouve pas directement que « Al-Khâfid » est un nom d'Allah."}], "numero_source": 22}$v$::jsonb, $v${"nom_arabe": "الْخَبِيرُ", "translit": "Al-Khabîr", "traduction": "Le Parfaitement Informé, Celui qui connaît parfaitement toute chose.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Khabîr signifie qu'Allah possède une connaissance parfaite, complète et profonde de toute chose.\n\nIl connaît ce qui est apparent comme ce qui est caché, les actes comme les intentions, les paroles prononcées comme les pensées que personne d'autre ne peut connaître.\n\nRien ne Lui échappe, même les réalités les plus discrètes ou les plus imperceptibles.\n\nSa connaissance n'est ni limitée, ni acquise progressivement : Allah connaît toute chose parfaitement.\n\nCe nom nous rappelle que nous pouvons être sincères devant Allah même lorsque personne ne voit nos efforts, nos difficultés ou nos bonnes intentions."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Allah connaît parfaitement notre situation, même lorsque nous ne savons pas expliquer ce que nous traversons.\n- Nos intentions ont une importance réelle auprès de Lui.\n- Nous devons chercher la sincérité dans nos actes, même lorsque personne ne nous observe.\n- Nous pouvons Lui confier ce que nous gardons au fond de nous."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ", "traduction": "« Les regards ne peuvent L'atteindre, cependant qu'Il saisit tous les regards. Et Il est le Subtil, le Parfaitement Informé. »", "ref": "Sourate Al-An'âm, 6:103.", "degre": "coran", "texte": "Ce verset cite deux noms d'Allah : Al-Latîf (اللَّطِيف), le Subtil, et Al-Khabîr (الْخَبِير), le Parfaitement Informé.\n\nAutre référence : Sourate Al-Mulk, 67:14."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous souhaitons Lui confier une situation complexe, une intention que les autres ne comprennent pas ou une difficulté que nous n'arrivons pas à exprimer."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui connais parfaitement toute chose, Tu connais ce que je montre et ce que je cache. Guide-moi vers ce qui est bon et purifie mes intentions. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 31}$v$::jsonb, $v${"nom_arabe": "الْغَفُورُ", "translit": "Al-Ghafûr", "traduction": "Le Très Pardonneur, Celui qui pardonne abondamment.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Ghafûr désigne Allah comme Celui dont le pardon est immense et qui pardonne abondamment à Ses serviteurs lorsqu'ils reviennent sincèrement vers Lui.\n\nCe nom exprime l'étendue de Son pardon : malgré les fautes répétées de l'être humain, la porte du repentir reste ouverte tant que les conditions du repentir sont réunies et que le délai accordé n'est pas dépassé.\n\nAllah connaît nos faiblesses, mais Il nous appelle à ne pas désespérer de Sa miséricorde.\n\nIl ne faut toutefois pas confondre l'espoir en Son pardon avec le fait de persister volontairement dans le péché sans repentir."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Ne jamais désespérer de la miséricorde d'Allah.\n- Reconnaître ses erreurs et demander pardon.\n- Délaisser le péché et regretter sincèrement ses actes.\n- Espérer le pardon d'Allah tout en faisant les efforts nécessaires pour changer."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Informe Mes serviteurs que c'est Moi le Pardonneur, le Très Miséricordieux. »", "ref": "Sourate Al-Hijr, 15:49.", "degre": "coran", "texte": "Autre référence : Sourate Az-Zumar, 39:53."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons pardon pour nos péchés, après une erreur ou dans le cadre de notre repentir."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Ghafûr, pardonne mes péchés, efface mes erreurs et aide-moi à ne pas retourner vers ce qui Te déplaît. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": null, "phonetique": null, "traduction": "Le Prophète ﷺ a enseigné notamment :\n\n« Ô Allah, Tu es Pardonneur et Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, 3513, invocation rapportée dans le hadith de 'Â'isha au sujet de la nuit du Destin.", "degre": "sahih", "texte": "Avis divergents sur son authenticité : At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf).", "note": "Important : cette invocation prophétique emploie le nom Al-'Afuww, et non Al-Ghafûr. Ne pas mélanger les deux noms dans la citation.", "divergence": "At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf)."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 34}$v$::jsonb, $v${"nom_arabe": "الْمُقِيتُ", "translit": "Al-Muqît", "traduction": "Le Pourvoyeur, Celui qui donne à chaque être ce qui lui est nécessaire.", "provenance": "Coran — nom attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqît est un nom dont les explications des savants comprennent notamment l'idée de Celui qui pourvoit aux besoins de Ses créatures, qui veille sur elles et qui a pleine capacité sur toute chose.\n\nAllah connaît les besoins de chaque être et rien ne Lui échappe.\n\nIl accorde les moyens de subsistance et les ressources nécessaires à Ses créatures selon Sa sagesse.\n\nCe nom nous rappelle que nos moyens de subsistance ne dépendent pas uniquement de nos efforts : ils sont également entre les mains d'Allah.\n\nCela ne signifie pas qu'il faut abandonner les efforts. Le croyant recherche les moyens licites tout en plaçant sa confiance en Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est à l'origine de notre subsistance.\n- Être reconnaissants pour les bienfaits reçus.\n- Rechercher notre subsistance par des moyens licites.\n- Ne pas laisser la peur du manque nous éloigner de notre confiance en Allah."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقِيتًۭا", "traduction": "« … et Allah veille sur toute chose. »", "ref": "Sourate An-Nisâ', 4:85 (fin du verset).", "degre": "coran", "texte": "Le verset contient le nom Al-Muqît dans l'expression arabe « مُقِيتًا ».\n\nAl-Muqît renvoie notamment à Celui qui veille sur toute chose, qui en assure la subsistance et qui a pouvoir sur elle. Il ne faut donc pas réduire son sens à la seule puissance."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faciliter notre subsistance, de nous accorder ce qui est bénéfique et de nous préserver du besoin."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muqît, accorde-moi une subsistance licite et bénie, pourvois à mes besoins et aide-moi à être reconnaissant envers Toi. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom attesté dans le Coran."}], "numero_source": 39}$v$::jsonb, $v${"nom_arabe": "الْوَلِيُّ", "translit": "Al-Waliyy", "traduction": "Le Protecteur, Celui qui prend en charge et soutient Ses serviteurs.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Waliyy désigne Allah comme Celui qui prend en charge Ses serviteurs croyants, les soutient, les guide et veille sur leurs affaires.\n\nIl est leur Protecteur et leur Allié véritable.\n\nSon soutien est parfait et se manifeste selon Sa sagesse. Cela ne signifie pas que les croyants seront exempts de toute épreuve, mais qu'ils peuvent rechercher auprès d'Allah la guidance, le secours et la protection.\n\nIl faut distinguer Al-Waliyy, avec le sens de Protecteur et Allié, de Al-Wâlî, qui apparaît plus loin dans la liste traditionnelle (fiche 77) et qui renvoie à la notion de Celui qui gouverne et administre."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Rechercher la protection et la guidance d'Allah.\n- Placer notre confiance en Lui.\n- Nous rapprocher d'Allah par la foi et les bonnes œuvres.\n- Ne pas faire dépendre notre sécurité spirituelle uniquement des créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah est le Protecteur de ceux qui ont la foi : Il les fait sortir des ténèbres vers la lumière. »", "ref": "Sourate Al-Baqara, 2:257.", "degre": "coran", "texte": "Autre référence : Sourate Ash-Shûrâ, 42:28."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah Sa protection, Sa guidance, Son soutien et Son aide dans nos affaires."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Waliyy, sois mon Protecteur, guide-moi vers ce qui Te satisfait et ne me laisse pas dépendre de mes seules forces. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 55}$v$::jsonb, $v${"nom_arabe": "الْحَمِيدُ", "translit": "Al-Hamîd", "traduction": "Le Digne de louange, Celui qui mérite toute louange.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hamîd signifie qu'Allah mérite toute louange en raison de Sa perfection, de Ses attributs et de Ses bienfaits.\n\nIl est digne d'être loué dans toutes les situations, car Sa perfection ne dépend pas de la reconnaissance des créatures.\n\nLes êtres humains Le louent pour Ses bienfaits, mais Il mérite également la louange pour ce qu'Il est.\n\nCe nom nous invite à remercier Allah, à Le glorifier et à reconnaître Ses bienfaits dans notre quotidien."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Louer Allah dans les moments faciles comme dans les moments difficiles.\n- Être reconnaissants pour Ses bienfaits.\n- Reconnaître que toute perfection appartient à Allah.\n- Ne pas attribuer à nous-mêmes le mérite exclusif de ce que nous possédons."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ", "traduction": "« … Allah Se suffit à Lui-même et Il est digne de louange. »", "ref": "Sourate Ibrâhîm, 14:8 (fin du verset).", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "إِنَّهُۥ حَمِيدٌۭ مَّجِيدٌۭ", "traduction": "« … Il est digne de louange et de gloire. »", "ref": "Sourate Hûd, 11:73 (fin du verset).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous louons Allah, Le remercions pour Ses bienfaits ou souhaitons Lui exprimer notre reconnaissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hamîd, à Toi revient toute louange. Aide-moi à reconnaître Tes bienfaits et à Te remercier sincèrement en toute circonstance. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 56}$v$::jsonb, $v${"nom_arabe": "الْمُحْيِي", "translit": "Al-Muhyî", "traduction": "Celui qui donne la vie et qui ressuscite les morts.", "provenance": "Coran — Allah donne la vie (action clairement attestée) ; forme nominale « Al-Muhyî » à préciser.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muhyî désigne Allah comme Celui qui donne la vie.\n\nIl est Celui qui donne l'existence aux êtres vivants, qui fait sortir la vie de ce qui paraît inerte et qui ressuscitera les morts au Jour dernier.\n\nLa vie appartient à Allah et dépend entièrement de Sa volonté.\n\nCe nom nous rappelle que notre existence est un bienfait immense et que nous devons utiliser notre vie pour accomplir ce qui plaît à notre Créateur."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est Celui qui donne la vie.\n- Être reconnaissants pour le bienfait de l'existence.\n- Se rappeler que la vie terrestre est temporaire.\n- Préparer notre retour vers Allah.\n- Ne jamais désespérer de Sa puissance."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Regarde donc les effets de la miséricorde d'Allah, comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts, et Il est Omnipotent. »", "ref": "Sourate Ar-Rûm, 30:50.", "degre": "coran", "texte": "Autre référence : Sourate Fussilat, 41:39."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de vivifier notre cœur par la foi, de nous guider et de nous accorder une vie consacrée à Son obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muhyî, donne vie à mon cœur par la foi, éloigne-moi de ce qui m'éloigne de Toi et aide-moi à consacrer ma vie à ce qui Te satisfait. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "FORME NOMINALE À PRÉCISER", "texte": "Le sens est directement confirmé par le Coran : Allah donne la vie et fait revivre les morts.\n\nLe statut de la forme « Al-Muhyî » comme nom indépendant dépend de la méthode retenue pour établir les noms divins.\n\nCette précision ne remet jamais en cause le fait qu'Allah donne la vie."}], "numero_source": 60}$v$::jsonb, $v${"nom_arabe": "الْحَيُّ", "translit": "Al-Hayy", "traduction": "Le Vivant, Celui dont la vie est parfaite et éternelle.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Hayy signifie qu'Allah est le Vivant, Celui dont la vie est parfaite et éternelle.\n\nSa vie n'a ni commencement ni fin. Elle ne dépend d'aucune créature et n'est accompagnée d'aucune faiblesse, fatigue ou disparition.\n\nLa vie des êtres humains est limitée et dépend de leur Créateur. La vie d'Allah, elle, est parfaite et éternelle, conformément à Sa majesté.\n\nCe nom nous rappelle que nous devons nous tourner vers Celui qui ne meurt jamais et qui ne connaît aucune faiblesse."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est le Vivant éternel.\n- Placer notre confiance en Celui qui ne disparaît jamais.\n- Comprendre que notre existence dépend entièrement de Lui.\n- Ne pas attribuer à Allah les limites propres aux créatures."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de nous soutenir, de nous guider et de nous accorder une foi vivante et sincère."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Hayy, Toi le Vivant qui ne meurs jamais, raffermis mon cœur dans la foi et aide-moi à vivre dans Ton obéissance. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ", "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Le Prophète ﷺ invoquait Allah avec cette formule.\n\n« Ô Vivant, ô Celui qui subsiste par Lui-même et par qui tout subsiste, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524.", "degre": "hasan", "texte": null, "note": "Jugé hasan, notamment par Al-Albânî. At-Tirmidhî qualifie sa transmission de « gharîb » (une seule chaîne connue), ce qui n'est pas un jugement de faiblesse."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 62}$v$::jsonb, $v${"nom_arabe": "الْقَيُّومُ", "translit": "Al-Qayyûm", "traduction": "Celui qui subsiste par Lui-même et qui fait subsister toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qayyûm signifie qu'Allah existe par Lui-même, sans dépendre de personne, tandis que toute la création dépend de Lui.\n\nIl maintient l'existence de toute chose et veille sur Sa création.\n\nIl n'a besoin ni de repos, ni de sommeil, ni d'aide. Rien ne subsiste sans Sa volonté et Sa puissance.\n\nCe nom nous rappelle notre dépendance totale envers Allah et Sa perfection absolue."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que nous dépendons entièrement d'Allah.\n- Ne pas placer notre confiance absolue dans les créatures.\n- Lui demander de nous soutenir dans toutes nos affaires.\n- Garder à l'esprit qu'Allah ne connaît aucune faiblesse."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. »", "ref": "Sourate Al-Baqara, 2:255.", "degre": "coran", "texte": "Autre référence : Sourate Âl 'Imrân, 3:2."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons Son soutien, Sa protection et Son aide dans les affaires importantes de notre vie."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qayyûm, Toi qui fais subsister toute chose, prends en charge mes affaires, raffermis ma foi et ne me laisse pas livré à mes seules faiblesses. »", "note": null}, {"type": "prophetique", "titre": "Invocation prophétique à distinguer", "arabe": "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ", "phonetique": "Yâ Hayyu, Yâ Qayyûm, bi-rahmatika astaghîth.", "traduction": "Le Prophète ﷺ invoquait Allah avec cette formule.\n\n« Ô Vivant, ô Celui qui subsiste par Lui-même et par qui tout subsiste, c'est par Ta miséricorde que je cherche secours. »", "ref": "Jâmi' At-Tirmidhî, 3524.", "degre": "hasan", "texte": null, "note": "Jugé hasan, notamment par Al-Albânî. At-Tirmidhî qualifie sa transmission de « gharîb » (une seule chaîne connue), ce qui n'est pas un jugement de faiblesse."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 63}$v$::jsonb, $v${"nom_arabe": "الْوَاجِدُ", "translit": "Al-Wâjid", "traduction": "Celui à qui rien ne manque, Celui qui ne perd ni ne manque de rien.", "provenance": "Statut comme nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Wâjid est traditionnellement expliqué comme Celui qui ne manque de rien et qui possède une richesse, une puissance et une perfection absolues.\n\nAllah n'a besoin d'aucune chose et aucune réalité ne Lui échappe.\n\nIl ne faut pas comprendre ce nom selon le sens humain du fait de chercher ou de trouver quelque chose après l'avoir perdu. Allah ne connaît ni perte, ni manque, ni recherche liée à une ignorance préalable.\n\nCe nom figure dans certaines énumérations traditionnelles des 99 noms, mais son établissement comme nom indépendant fait l'objet de discussions. La liste détaillée populaire attribuée au hadith des 99 noms ne constitue pas, à elle seule, une preuve incontestable de chaque nom."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah n'a besoin de personne.\n- Comprendre que toute créature dépend de Lui.\n- Éviter de nous croire indépendants de notre Créateur.\n- Placer notre confiance en Celui qui possède toute perfection."}, {"type": "preuve", "titre": "Éclairage sur le sens (pas une preuve du nom)", "arabe": "يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ", "traduction": "« Ô hommes ! Vous êtes les indigents ayant besoin d'Allah, et Allah est Celui qui Se suffit à Lui-même, le Digne de louange. »", "ref": "Sourate Fâtir, 35:15.", "degre": "coran", "texte": "Ce verset établit qu'Allah est parfaitement indépendant de Ses créatures et que toutes les créatures ont besoin de Lui. Il éclaire un aspect du sens que certains associent à Al-Wâjid, mais ne prouve pas directement que ce terme est un nom divin établi."}, {"type": "divergence", "titre": "À savoir – Divergence entre les savants", "texte": "- Présent dans la liste traditionnelle des 99 noms.\n- Son statut comme nom indépendant est discuté.\n- Ne pas présenter la liste détaillée attribuée à At-Tirmidhî comme une preuve authentique incontestable de ce nom."}, {"type": "texte", "titre": "Quand évoquer Allah par ce nom", "texte": "On peut méditer sur le fait qu'Allah n'a besoin de rien et que toute la création dépend de Lui. Par prudence, ne pas présenter une invocation spécifique avec Al-Wâjid comme formule prophétique établie."}, {"type": "invocation", "titre": "Exemple de rappel personnel", "texte": "« Ô Allah, Toi qui n'as besoin de rien, aide-moi à reconnaître ma dépendance envers Toi et à ne rechercher que Ton agrément. »", "note": "Formulation personnelle, et non invocation prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "STATUT DISCUTÉ", "texte": null}], "numero_source": 64}$v$::jsonb, $v${"nom_arabe": "الْقَادِرُ", "translit": "Al-Qâdir", "traduction": "Le Tout-Puissant, Celui qui a pouvoir sur toute chose.", "provenance": "Coran — nom explicitement attesté.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Qâdir signifie qu'Allah possède une puissance parfaite et qu'Il est capable de toute chose.\n\nRien ne peut Le limiter ou L'empêcher d'accomplir ce qu'Il veut.\n\nLa puissance des créatures est limitée et dépend de Lui. La puissance d'Allah est absolue.\n\nCe nom nous apprend à ne jamais considérer une difficulté comme impossible pour Allah."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître la puissance absolue d'Allah.\n- Garder espoir dans les situations difficiles.\n- Ne pas désespérer de Sa capacité à changer une situation.\n- Placer notre confiance en Lui tout en prenant les moyens licites."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًۭا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ", "traduction": "« Dis : Il est capable (Al-Qâdir) de faire venir contre vous un châtiment d'en haut ou de dessous vos pieds… »", "ref": "Sourate Al-An'âm, 6:65 (début du verset).", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ", "traduction": "« Celui-là n'est-Il pas capable de faire revivre les morts ? »", "ref": "Sourate Al-Qiyâma, 75:40.", "degre": "coran", "texte": "Le verset emploie « بِقَادِرٍ » : Allah est capable de ressusciter les morts."}, {"type": "preuve", "titre": "Autre preuve dans le Coran", "arabe": "قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةًۭ", "traduction": "« Dis : Certes, Allah est capable de faire descendre un signe. »", "ref": "Sourate Al-An'âm, 6:37 (extrait).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous faisons face à une difficulté qui nous semble insurmontable ou lorsque nous demandons à Allah de faciliter une affaire."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qâdir, Tu es capable de toute chose. Facilite mes affaires, éloigne de moi ce qui est mauvais et guide-moi vers ce qui est bon. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Nom explicitement attesté dans le Coran."}], "numero_source": 68}$v$::jsonb, $v${"nom_arabe": "الْمُقَدِّمُ", "translit": "Al-Muqaddim", "traduction": "Celui qui fait avancer et qui place en avant selon Sa sagesse.", "provenance": "Sunna authentique.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muqaddim est traditionnellement expliqué comme Celui qui fait avancer, donne la priorité ou place en avant ce qu'Il veut selon Sa sagesse.\n\nAllah décide de l'ordre des événements et de ce qui doit être avancé ou retardé.\n\nCe nom est souvent associé à Al-Mu'akhkhir, Celui qui retarde.\n\nLes deux noms sont cités ensemble dans une invocation prophétique authentique. Cette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître que les événements se déroulent selon la sagesse d'Allah.\n- Ne pas désespérer lorsque certaines choses prennent du temps.\n- Demander à Allah de faciliter les bonnes initiatives.\n- Faire preuve de patience et de confiance dans Ses décisions."}, {"type": "preuve", "titre": "Preuve authentique", "arabe": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "traduction": "Le Prophète ﷺ disait dans une invocation :\n\nAnta al-Muqaddimu wa anta al-Mu'akhkhir.\n\n« Tu es Celui qui fait avancer et Tu es Celui qui retarde. »", "ref": "Sahîh Al-Boukhârî 1120 et Sahîh Mouslim 771.", "degre": "sahih", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de faire avancer une affaire bénéfique, de faciliter une bonne décision et de nous guider vers ce qui est meilleur."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et retarder selon Ta sagesse, fais avancer pour moi ce qui est bénéfique et éloigne ce qui n'est pas bon pour ma religion et ma vie. »", "note": "Cette formulation est personnelle ; la preuve ci-dessus est la formule rapportée dans le hadith."}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA AUTHENTIQUE", "texte": "Attesté explicitement dans la Sunna authentique, dans l'invocation rapportée par Al-Boukhârî et Mouslim.\n\nCette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}], "numero_source": 70}$v$::jsonb, $v${"nom_arabe": "الْمُؤَخِّرُ", "translit": "Al-Mu'akhkhir", "traduction": "Celui qui retarde, Celui qui fait passer après.", "provenance": "Sunna authentique.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui décide de l'ordre des événements et de leur moment. Il peut retarder une chose, une échéance ou une situation selon Sa sagesse parfaite. Ce qui nous semble tarder n'échappe jamais à Sa connaissance ni à Son décret.\n\nCe Nom est à comprendre en complément d'Al-Muqaddim : Allah est Celui qui fait avancer et Celui qui fait reculer ou retarder. Rien ne se produit indépendamment de Sa volonté."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Faire preuve de patience lorsque les choses prennent du temps.\n- Ne pas désespérer lorsqu'une demande semble tarder à être exaucée.\n- Comprendre que notre perception du moment opportun n'est pas toujours celle qui correspond à la sagesse divine.\n- Placer notre confiance en Allah sans cesser d'accomplir les causes permises."}, {"type": "preuve", "titre": "Preuve authentique", "arabe": "أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ", "traduction": "Le Prophète ﷺ disait dans une invocation :\n\nAnta al-Muqaddimu wa anta al-Mu'akhkhir.\n\n« Tu es Celui qui fait avancer et Tu es Celui qui retarde. »", "ref": "Sahîh Al-Boukhârî 1120 et Sahîh Mouslim 771.", "degre": "sahih", "texte": "Authenticité : hadith authentique, rapporté par Al-Boukhârî et Mouslim."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "On peut évoquer ce Nom lorsqu'on demande à Allah de gérer nos affaires avec sagesse, de nous accorder le bon moment pour une chose ou de nous préserver d'une précipitation nuisible."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui fais avancer et qui retardes selon Ta sagesse, accorde-moi ce qui est bon au moment qui est le meilleur pour moi. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA AUTHENTIQUE", "texte": "Attesté explicitement dans la Sunna authentique, dans l'invocation rapportée par Al-Boukhârî et Mouslim.\n\nCette invocation authentique ne permet pas d'inventer des mérites particuliers ni un nombre de répétitions pour ces deux noms."}], "numero_source": 71}$v$::jsonb, $v${"nom_arabe": "الْعَفُوُّ", "translit": "Al-'Afuww", "traduction": "Celui qui efface les péchés et pardonne abondamment.", "provenance": "Coran et Sunna.", "statut": "etabli", "classement": "coran_sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-'Afuww. Il pardonne les fautes de Ses serviteurs et peut en effacer les traces. Son pardon est immense et Sa miséricorde dépasse ce que les êtres humains peuvent imaginer.\n\nCe Nom nous rappelle que le croyant ne doit jamais désespérer du pardon d'Allah. Il doit toutefois se repentir sincèrement et s'efforcer de délaisser le péché."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Ne jamais perdre espoir dans le pardon d'Allah.\n- Reconnaître ses erreurs et revenir sincèrement vers Lui.\n- Apprendre à pardonner aux autres lorsque cela est possible et juste.\n- Ne pas banaliser les péchés sous prétexte qu'Allah pardonne."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا", "traduction": "« Allah est certes Celui qui efface les fautes et qui pardonne. »", "ref": "Coran, sourate An-Nisâ' (4), verset 99.", "degre": "coran", "texte": "Autres références : Coran 4:149 et 22:60."}, {"type": "prophetique", "titre": "Invocation prophétique authentique", "arabe": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "phonetique": "Allâhumma innaka 'Afuwwun tuhibbu al-'afwa fa'fu 'annî.", "traduction": "« Ô Allah, Tu es Celui qui efface les fautes, Tu aimes le pardon, alors pardonne-moi. »", "ref": "Jâmi' At-Tirmidhî, 3513.", "degre": "sahih", "texte": "'Â'isha رضي الله عنها demanda au Prophète ﷺ quelle invocation prononcer durant la Nuit du Destin. Il lui enseigna cette invocation.", "note": "Avis divergents sur son authenticité : At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf).", "divergence": "At-Tirmidhî : hasan sahih. Al-Albânî : sahih. Zubair 'Alî Zaï : faible (da'îf)."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande pardon à Allah, particulièrement pendant les moments propices au repentir, comme les dernières nuits du Ramadan."}, {"type": "invocation", "titre": "Exemple d'invocation", "texte": "« Ô Allah, Tu es Al-'Afuww, pardonne-moi, efface mes fautes et accepte mon repentir. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN ET SUNNA", "texte": "Attesté explicitement dans le Coran. L'invocation rapportée par At-Tirmidhî fait l'objet d'avis divergents sur son authenticité."}], "numero_source": 81}$v$::jsonb, $v${"nom_arabe": "ذُو الْجَلَالِ وَالْإِكْرَامِ", "translit": "Dhul-Jalâli wal-Ikrâm", "traduction": "Le Détenteur de la majesté et de la générosité.", "provenance": "Coran — expression explicitement attestée.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui possède toute majesté, toute grandeur et toute perfection. Il est également Celui dont la générosité et les bienfaits sont immenses.\n\nCette appellation réunit deux réalités : la majesté d'Allah, qui inspire le respect et la vénération, et Sa générosité, qui suscite l'amour, l'espérance et la gratitude."}, {"type": "texte", "titre": "Ce que cette appellation nous enseigne", "texte": "- Vénérer Allah et reconnaître Sa grandeur.\n- L'aimer, espérer Sa générosité et Lui être reconnaissant.\n- Ne pas oublier que tous les bienfaits viennent de Lui.\n- Réunir dans notre adoration le respect d'Allah et l'espoir en Sa miséricorde."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ", "traduction": "« Seule subsistera la Face de ton Seigneur, Détenteur de la majesté et de la générosité. »", "ref": "Coran, sourate Ar-Rahmân (55), verset 27.", "degre": "coran", "texte": "Le mot « al-Ikrâm » est riche : il évoque la générosité, mais aussi l'honneur, la noblesse et la munificence. Certaines traductions disent « noblesse ».\n\nAutre référence : Coran, sourate Ar-Rahmân (55), verset 78."}, {"type": "texte", "titre": "Quand invoquer Allah par cette appellation", "texte": "Lorsqu'on souhaite glorifier Allah, Lui demander Ses bienfaits et exprimer sa gratitude envers Lui."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui détiens la majesté et la générosité, accorde-moi Ta miséricorde et rapproche-moi de ce qui Te satisfait. »", "note": null}, {"type": "authenticite", "titre": "Authenticité de l'appellation", "badge": "CORAN", "texte": "Expression explicitement attestée dans le Coran."}], "numero_source": 84}$v$::jsonb) order by 1;
